// Stable, machine-readable error codes and the HTTP status each one maps to.
// Documented in the README; clients (the web app) switch on `code`, never on the message.
const ERROR_HTTP_STATUS = {
  INVALID_ORDER_ID: 400,
  INVALID_STATUS_FILTER: 400,
  ORDER_NOT_FOUND: 404,
  ROUTE_NOT_FOUND: 404,
  INVALID_TRANSITION: 409,
  INTERNAL_ERROR: 500,
};

// An expected, client-facing error. Business code throws it; the error
// middleware turns it into `{ error: { code, message, details } }`.
class AppError extends Error {
  constructor(code, message, details) {
    super(message);
    this.name = 'AppError';
    this.code = code;
    this.httpStatus = ERROR_HTTP_STATUS[code];
    this.details = details;
  }
}

module.exports = { AppError, ERROR_HTTP_STATUS };

