    {
      displayName: 'unit',
      testEnvironment: 'node',
      testMatch: ['<rootDir>/tests/unit/**/*.test.js'],
    },
  ],
};

// Shared test fixtures. Every test uses this frozen `now` (the spec's worked-example clock),
// never the real clock.
const NOW = new Date('2026-06-15T12:00:00Z');

const MS_PER_MINUTE = 60 * 1000;
const minutesAgo = (minutes) => new Date(NOW.getTime() - minutes * MS_PER_MINUTE);
const minutesFromNow = (minutes) => new Date(NOW.getTime() + minutes * MS_PER_MINUTE);

const MENU = {
  grilledSalmon: { name: 'Grilled Salmon', prep_time_minutes: 20 },
  caesarSalad: { name: 'Caesar Salad', prep_time_minutes: 10 },
  margheritaPizza: { name: 'Margherita Pizza', prep_time_minutes: 12 },
};
const item = (menuItem, quantity) => ({ ...menuItem, quantity });

// A neutral order worth exactly 10 points (delivery base only), so each test
// changes one input and can assert on that component alone.
function buildOrder(overrides = {}) {
  return {
    id: 1,
    customer_name: 'Test',
    type: 'delivery',
    is_vip: false,
    status: 'received',
    placed_at: NOW,
    promised_at: null,
    items: [],
    ...overrides,
  };
}

module.exports = { NOW, minutesAgo, minutesFromNow, MENU, item, buildOrder };

const { computeScore } = require('../../src/modules/priority');
