  });

  test('quantity multiplies prep time: 3x Salmon = 60 min -> cap of 20', () => {
    expect(computeScore(buildOrder({ items: [item(MENU.grilledSalmon, 3)] }), NOW)).toBe(BASE + 20);
  });

