'use strict';

// Demo data (spec §9.5). Every timestamp is relative to the moment the seed runs,
// so the demo never goes stale: re-run `npm run db:setup` to refresh it.
// Scores in the comments are the values right after seeding.

const MENU_ITEMS = [
  { name: 'Caesar Salad', category: 'starter', prep_time_minutes: 10 },
  { name: 'Bruschetta', category: 'starter', prep_time_minutes: 8 },
  { name: 'Grilled Salmon', category: 'main_course', prep_time_minutes: 20 },
  { name: 'Margherita Pizza', category: 'main_course', prep_time_minutes: 12 },
  { name: 'Ribeye Steak', category: 'main_course', prep_time_minutes: 25 },
  { name: 'Mushroom Risotto', category: 'main_course', prep_time_minutes: 18 },
  { name: 'Tiramisu', category: 'dessert', prep_time_minutes: 6 },
  { name: 'Chocolate Lava Cake', category: 'dessert', prep_time_minutes: 15 },
  { name: 'Lemonade', category: 'drink', prep_time_minutes: 2 },
  { name: 'Espresso', category: 'drink', prep_time_minutes: 1 },
];

// `placed` = minutes ago, `promised` = minutes from now (negative = in the past), null = no promise.
const ORDERS = [
  // Wait-time cap: 95 min waiting -> 40 points (the max). 30 + 40 + 5 = 75
  { customer_name: 'Ana Souza', type: 'dine_in', is_vip: false, status: 'received', placed: 95, promised: null,
    items: [['Mushroom Risotto', 1]] },

  // Spec Example B: delivery VIP, promise in 20 min. 10 + 20 + 5 + 25 + 0 = 60
  { customer_name: 'Felipe Costa', type: 'delivery', is_vip: true, status: 'received', placed: 10, promised: 20,
    items: [['Margherita Pizza', 1]] },
  // Spec Example A: dine_in, no promise. 30 + 15 + 15 = 60 -> ties with Felipe; Felipe ranks first
  // (he has a promised_at). Placed exactly 20 min apart so both gain wait points at the same
  // moment and the tie holds for ~50 min. Also shows a lower base type matching a higher one.
  { customer_name: 'Elena Rossi', type: 'dine_in', is_vip: false, status: 'received', placed: 30, promised: null,
    items: [['Grilled Salmon', 2], ['Caesar Salad', 1], ['Espresso', 1]] },

  // Complexity cap: 2x25 + 20 = 70 prep minutes -> 20 points (the max). 30 + 0 + 20 = 50
  { customer_name: 'Bruno Lima', type: 'dine_in', is_vip: false, status: 'preparing', placed: 5, promised: null,
    items: [['Ribeye Steak', 2], ['Grilled Salmon', 1]] },
  // 31-60 min promise bucket: 20 + 10 + 15 + 5 = 50 (ties with Bruno, ranks first: has a promise)
  { customer_name: 'Gabi Martins', type: 'takeout', is_vip: false, status: 'preparing', placed: 20, promised: 45,
    items: [['Caesar Salad', 1], ['Tiramisu', 1]] },

  // Score tie broken by promised_at: identical orders placed at the same instant, both promises
  // more than 60 min away (0 points). 20 + 5 = 25 each; Carla (earlier promise) ranks above Diego.
  // Stable for ~2 hours, until Carla's promise enters the 60-minute bucket.
  { customer_name: 'Carla Dias', type: 'takeout', is_vip: false, status: 'received', placed: 15, promised: 180,
    items: [['Margherita Pizza', 1], ['Lemonade', 1]] },
  { customer_name: 'Diego Alves', type: 'takeout', is_vip: false, status: 'received', placed: 15, promised: 240,
    items: [['Margherita Pizza', 1], ['Lemonade', 1]] },

  // Not in the active queue.
  { customer_name: 'Hugo Pereira', type: 'takeout', is_vip: false, status: 'ready', placed: 40, promised: 5,
    items: [['Bruschetta', 2]] },
  { customer_name: 'Iris Melo', type: 'delivery', is_vip: true, status: 'picked_up', placed: 120, promised: -60,
    items: [['Chocolate Lava Cake', 1]] },
  { customer_name: 'João Nunes', type: 'dine_in', is_vip: false, status: 'cancelled', placed: 25, promised: null,
    items: [['Ribeye Steak', 1]] },
];

/** @type {import('sequelize-cli').Migration} */
module.exports = {
  async up(queryInterface) {
