// Turns every error into the API's single error shape: { error: { code, message, details? } }.
const { AppError } = require('../errors');

function notFoundHandler(req, res) {
  res.status(404).json({
    error: { code: 'ROUTE_NOT_FOUND', message: `No route for ${req.method} ${req.path}.` },
  });
}

// Express recognizes error middleware by its four parameters, so `_next` must stay.
// eslint-disable-next-line no-unused-vars
function errorHandler(error, req, res, _next) {
  if (error instanceof AppError) {
    res.status(error.httpStatus).json({
      error: { code: error.code, message: error.message, details: error.details },
    });
    return;
  }

  // Unexpected: log the real cause for us, return nothing internal to the client.
  console.error(error);
  res.status(500).json({ error: { code: 'INTERNAL_ERROR', message: 'Unexpected server error.' } });
}

module.exports = { notFoundHandler, errorHandler };

