// Turns every error into the API's single error shape: { error: { code, message, details? } }.
const { AppError } = require('../errors');

function sendError(res, error) {
  res.status(error.httpStatus).json({
    error: { code: error.code, message: error.message, details: error.details },
  });
}

function notFoundHandler(req, res) {
  sendError(res, new AppError('ROUTE_NOT_FOUND', `No route for ${req.method} ${req.path}.`));
}

// Express recognizes error middleware by its four parameters.
function errorHandler(error, req, res, next) {
  // A response already in flight cannot be replaced; let Express close the connection.
  if (res.headersSent) return next(error);

  if (error instanceof AppError) return sendError(res, error);

  // Errors Express raises itself for a bad request (e.g. malformed URL encoding) carry a 4xx status.
  if (error.status >= 400 && error.status < 500) {
    return sendError(res, new AppError('BAD_REQUEST', 'The request is malformed.'));
  }

  // Unexpected: log the real cause for us, return nothing internal to the client.
  console.error(error);
  return sendError(res, new AppError('INTERNAL_ERROR', 'Unexpected server error.'));
}

module.exports = { notFoundHandler, errorHandler };

