// Data access for orders: Sequelize queries, includes and filters. No business rules here;
// callers decide which statuses to load and which transition is legal.
const { Order, OrderItem, MenuItem } = require('../schema/models');

const WITH_ITEMS = {
  include: [{ model: OrderItem, as: 'items', include: [{ model: MenuItem, as: 'menu_item' }] }],
};

// Plain object for the module layer: no Sequelize instances leak out, and each line carries
// the menu data the score needs (prep_time_minutes) and the UI shows (name).
function toPlainOrder(orderInstance) {
  const { items, ...order } = orderInstance.get({ plain: true });
  return {
    ...order,
    items: items
      .sort((a, b) => a.id - b.id)
      .map((line) => ({
        menu_item_id: line.menu_item_id,
        name: line.menu_item.name,
        prep_time_minutes: line.menu_item.prep_time_minutes,
        quantity: line.quantity,
      })),
  };
}

async function findOrdersByStatuses(statuses) {
  const orders = await Order.findAll({ ...WITH_ITEMS, where: { status: statuses } });
  return orders.map(toPlainOrder);
}

async function findOrderById(id) {
  const order = await Order.findByPk(id, WITH_ITEMS);
  return order ? toPlainOrder(order) : null;
}

// Moves the order only if it is still in `fromStatus`, as one atomic UPDATE ... WHERE.
// Returns false when another request changed the status first (e.g. a double click).
async function updateStatusIfCurrent(id, fromStatus, toStatus) {
  const [affectedRows] = await Order.update({ status: toStatus }, { where: { id, status: fromStatus } });
  return affectedRows === 1;
}

module.exports = { findOrdersByStatuses, findOrderById, updateStatusIfCurrent };

