import { ToggleButton, ToggleButtonGroup } from '@mui/material'
import type { QueueFilter as Filter } from '../api/orders'

interface QueueFilterProps {
  value: Filter
  onChange: (filter: Filter) => void
}

export function QueueFilter({ value, onChange }: QueueFilterProps) {
  return (
    <ToggleButtonGroup
      size="small"
      exclusive
      value={value}
      // MUI passes null when the selected button is clicked again; keep the current filter.
      onChange={(_event, next: Filter | null) => next && onChange(next)}
      aria-label="Queue filter"
    >
      <ToggleButton value="active">Active queue</ToggleButton>
      <ToggleButton value="received">Received</ToggleButton>
      <ToggleButton value="preparing">Preparing</ToggleButton>
    </ToggleButtonGroup>
  )
}

