// Presentation only: labels, colors and text formatting. No business rules live here —
// which actions exist for an order, its score and its position all come from the API.
import type { ChipProps } from '@mui/material'
import type { OrderAction, OrderItem, OrderStatus, OrderType } from './api/orders'

export const ORDER_TYPE_LABEL: Record<OrderType, string> = {
  dine_in: 'Dine-in',
  takeout: 'Takeout',
  delivery: 'Delivery',
}

export const STATUS_LABEL: Record<OrderStatus, string> = {
  received: 'Received',
  preparing: 'Preparing',
  ready: 'Ready',
  picked_up: 'Picked up',
  cancelled: 'Cancelled',
}

export const STATUS_COLOR: Record<OrderStatus, ChipProps['color']> = {
  received: 'info',
  preparing: 'warning',
  ready: 'success',
  picked_up: 'default',
  cancelled: 'default',
}

export const ACTION_LABEL: Record<OrderAction, string> = {
  start: 'Start',
  ready: 'Mark ready',
  pickup: 'Picked up',
  cancel: 'Cancel',
}

/** "2× Grilled Salmon, 1× Caesar Salad" */
export function formatItems(items: OrderItem[]): string {
  return items.map((item) => `${item.quantity}× ${item.name}`).join(', ')
}

/** Local wall-clock time, e.g. "14:35". */
export function formatTime(isoTimestamp: string): string {
  return new Date(isoTimestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

