import { useCallback, useEffect, useRef, useState } from 'react'
import { fetchQueue, toApiError } from '../api/orders'
import type { ApiError, QueueFilter, QueueResponse } from '../api/orders'

/** Loads the queue for `filter` and reloads it on demand. Keeps the last good data while reloading. */
export function useQueue(filter: QueueFilter) {
  const [data, setData] = useState<QueueResponse | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<ApiError | null>(null)

  // Only the latest request may update state: switching filters quickly must not let
  // an older, slower response overwrite the newer one.
  const latestRequest = useRef(0)

  const reload = useCallback(async () => {
    const requestId = ++latestRequest.current
    setLoading(true)
    try {
      const result = await fetchQueue(filter)
      if (requestId !== latestRequest.current) return
      setData(result)
      setError(null)
    } catch (err) {
      if (requestId !== latestRequest.current) return
      setError(toApiError(err))
    } finally {
      if (requestId === latestRequest.current) setLoading(false)
    }
  }, [filter])

  useEffect(() => {
    void reload()
  }, [reload])

  return { orders: data?.orders ?? null, generatedAt: data?.generated_at ?? null, loading, error, reload }
}

