import { chromium } from 'playwright-core'

const OUT = process.argv[2]
const BASE = 'http://localhost:5173'
const log = (...a) => console.log(...a)

const browser = await chromium.launch({ channel: 'msedge', headless: true })
const page = await browser.newPage({ viewport: { width: 1400, height: 720 } })
const consoleErrors = []
page.on('console', (m) => m.type() === 'error' && consoleErrors.push(m.text()))

await page.goto(BASE)
await page.getByRole('row').nth(1).waitFor()

// 1. Table order must equal API order.
const api = await (await fetch(`${BASE}/orders/queue`)).json()
const rowNames = await page.locator('tbody tr td:nth-child(2)').allInnerTexts()
log('API order :', api.orders.map((o) => `${o.customer_name}(${o.score})`).join(', '))
log('UI order  :', rowNames.map((t) => t.split('\n')[0].replace(/#\d+/, '').trim()).join(', '))
log('headers   :', (await page.locator('thead th').allInnerTexts()).join(' | '))
log('row 1     :', (await page.locator('tbody tr').first().innerText()).replace(/\s+/g, ' '))
await page.screenshot({ path: `${OUT}/1-queue.png` })

// 2. Buttons per status.
for (const o of api.orders.slice(0, 5)) {
  const labels = await page.locator('tbody tr', { hasText: `#${o.id}` }).getByRole('button').allInnerTexts()
  log(`buttons #${o.id} ${o.status.padEnd(9)} api=${o.allowed_actions.join(',').padEnd(12)} ui=${labels.join(',')}`)
}

// 3. Rejection visible on screen: "another tab" starts the order first, then we click Start.
const target = api.orders.find((o) => o.status === 'received')
await fetch(`${BASE}/orders/${target.id}/start`, { method: 'POST' })
await page.locator('tbody tr', { hasText: `#${target.id}` }).getByRole('button', { name: /^Start/ }).click()
const alert = page.getByRole('alert')
await alert.waitFor()
log('alert     :', (await alert.innerText()).replace(/\s+/g, ' '))
await page.waitForTimeout(400)
log(`row #${target.id} after reload buttons:`, await page.locator('tbody tr', { hasText: `#${target.id}` }).getByRole('button').allInnerTexts())
await page.screenshot({ path: `${OUT}/2-rejected.png` })

// 4. Filter: preparing only.
await page.getByRole('button', { name: 'Preparing', exact: true }).click()
await page.waitForTimeout(400)
log('preparing :', (await page.locator('tbody tr td:nth-child(8)').allInnerTexts()).join(','))
await page.screenshot({ path: `${OUT}/3-preparing.png` })

// 5. Empty state: mark every preparing order ready (they leave the queue).
while ((await page.getByRole('button', { name: /^Mark ready/ }).count()) > 0) {
  await page.getByRole('button', { name: /^Mark ready/ }).first().click()
  await page.waitForTimeout(400)
}
log('empty     :', await page.locator('tbody').innerText())
await page.screenshot({ path: `${OUT}/4-empty.png` })

log('console errors:', consoleErrors.length ? consoleErrors : 'none')
await browser.close()

