import { useCallback, useEffect, useState } from 'react'
import { fetchQueue, toApiError } from '../api/orders'
import type { ApiError, QueueFilter, QueueResponse } from '../api/orders'

interface QueueResult {
  filter: QueueFilter // the filter `data` was loaded for
  requestKey: string // the request this result answers
  data: QueueResponse | null // last successful response, kept while refreshing or after an error
  error: ApiError | null
}

/** Loads the queue for `filter`; `reload()` fetches it again. */
export function useQueue(filter: QueueFilter) {
  const [reloadCount, setReloadCount] = useState(0)
  const [result, setResult] = useState<QueueResult | null>(null)

  // Identifies the request the screen currently wants. `loading` is derived from it instead of
  // being stored, so the effect below never has to set state synchronously.
  const requestKey = `${filter}#${reloadCount}`

  useEffect(() => {
    // Set by the cleanup when the filter changes or reload() runs again before this request
    // finishes: a slower, older response must not overwrite a newer one.
    let ignore = false

    fetchQueue(filter).then(
      (data) => {
        if (!ignore) setResult({ filter, requestKey, data, error: null })
      },
      (error: unknown) => {
        if (ignore) return
        setResult((previous) => ({
          filter,
          requestKey,
          data: previous?.filter === filter ? previous.data : null,
          error: toApiError(error),
        }))
      },
    )

    return () => {
      ignore = true
    }
  }, [filter, requestKey])

  const reload = useCallback(() => setReloadCount((count) => count + 1), [])

  // Rows loaded for another filter are never shown: they would contradict the selected filter
  // (and offer actions on orders that do not belong to the view). A refresh keeps the rows.
  const current = result?.filter === filter ? result : null

  return {
    orders: current?.data?.orders ?? null,
    generatedAt: current?.data?.generated_at ?? null,
    loading: result?.requestKey !== requestKey,
    error: current?.error ?? null,
    reload,
  }
}

