      (data) => {
        if (!ignore) setResult({ key: requestKey, data, error: null })
      },
      (error: unknown) => {
        if (!ignore) setResult((previous) => ({ key: requestKey, data: previous?.data ?? null, error: toApiError(error) }))
      },
