const uiIds = (await page.locator('tbody tr td:nth-child(2) span').allInnerTexts()).map((t) => Number(t.replace('#', '')))
check('§8 rows in exactly the API order', JSON.stringify(uiIds) === JSON.stringify(queue.map((o) => o.id)), uiIds.join(','))
const uiScores = (await page.locator('tbody tr td:nth-child(1)').allInnerTexts()).map(Number)
check('§7/§8 score shown = score from API', JSON.stringify(uiScores) === JSON.stringify(queue.map((o) => o.score)), uiScores.join(','))
check('§5 default queue only received/preparing', queue.every((o) => ['received', 'preparing'].includes(o.status)))
check('§9.5 seed tie broken by promised_at (Chloe before David, both 25)',
  queue.findIndex((o) => o.customer_name === 'Chloe Davis') < queue.findIndex((o) => o.customer_name === 'David Reed') &&
  queue.find((o) => o.customer_name === 'Chloe Davis').score === queue.find((o) => o.customer_name === 'David Reed').score)
check('§8 VIP badge on VIP orders only',
  (await page.locator('tbody tr', { has: page.getByText('VIP', { exact: true }) }).count()) === queue.filter((o) => o.is_vip).length)
await page.screenshot({ path: `${OUT}/a-queue.png` })

// §8 only the valid action per row; cancel only for received
let buttonsOk = true
for (const o of queue) {
  const labels = (await rowOf(o.id).getByRole('button').allInnerTexts()).map((l) => l.toLowerCase())
  const expected = o.allowed_actions.map((a) => ({ start: 'start', ready: 'mark ready', pickup: 'picked up', cancel: 'cancel' })[a])
  if (JSON.stringify(labels) !== JSON.stringify(expected)) buttonsOk = false
  if (labels.includes('cancel') && o.status !== 'received') buttonsOk = false
}
check('§8 each row shows only its valid actions; Cancel only on received', buttonsOk)

// §8 cancel a received order
const toCancel = queue.find((o) => o.status === 'received' && o.customer_name === 'David Reed')
await rowOf(toCancel.id).getByRole('button', { name: /^Cancel/ }).click()
await settle()
check('§8 cancel: order leaves the active queue', (await rowOf(toCancel.id).count()) === 0)

// §6 lifecycle via UI: start -> preparing -> ready leaves the queue
const toStart = (await api('/orders/queue')).body.orders.find((o) => o.status === 'received')
await rowOf(toStart.id).getByRole('button', { name: /^Start/ }).click()
await settle()
check('§6 start: status becomes Preparing on screen', (await rowOf(toStart.id).innerText()).includes('Preparing'))
await rowOf(toStart.id).getByRole('button', { name: /^Mark ready/ }).click()
await settle()
check('§5 ready order leaves the active queue', (await rowOf(toStart.id).count()) === 0)

// §6 server enforcement when the API is called directly
const preparing = (await api('/orders/queue?status=preparing')).body.orders[0]
const direct = await api(`/orders/${preparing.id}/start`, { method: 'POST' })
check('§6 direct API call: start on preparing -> 409 INVALID_TRANSITION', direct.status === 409 && direct.body.error.code === 'INVALID_TRANSITION')
const pickedUpEarly = await api(`/orders/${preparing.id}/pickup`, { method: 'POST' })
check('§6 direct API call: skipping a step -> 409', pickedUpEarly.status === 409)
const ready = (await api(`/orders/${toStart.id}/pickup`, { method: 'POST' }))
check('§6 ready -> picked_up succeeds', ready.status === 200 && ready.body.order.status === 'picked_up')
const terminal = await api(`/orders/${toStart.id}/pickup`, { method: 'POST' })
check('§6 terminal: picked_up cannot move again -> 409', terminal.status === 409)

// §8 rejected transition is visible on screen (another client acted first)
const victim = (await api('/orders/queue?status=received')).body.orders[0]
await page.reload(); await settle()
await api(`/orders/${victim.id}/start`, { method: 'POST' })
await rowOf(victim.id).getByRole('button', { name: /^Start/ }).click()
const alert = page.getByRole('alert')
await alert.waitFor()
const alertText = (await alert.innerText()).replace(/\s+/g, ' ')
check('§8 API rejection visible on screen with its code', alertText.includes('INVALID_TRANSITION'), alertText)
await settle()
check('     ...and the row then shows the real status', (await rowOf(victim.id).innerText()).includes('Preparing'))
await page.screenshot({ path: `${OUT}/b-rejected.png` })
await alert.getByRole('button', { name: 'Close' }).click()

// §8 filters
for (const [name, status] of [['Received', 'received'], ['Preparing', 'preparing']]) {
  await page.getByRole('button', { name, exact: true }).click()
  await settle()
  const chips = await page.locator('tbody tr td:nth-child(8)').allInnerTexts()
  const expectedCount = (await api(`/orders/queue?status=${status}`)).body.orders.length
  check(`§8 filter "${name}" shows only ${status} orders`, chips.length === expectedCount && chips.every((c) => c === name), chips.join(','))
}

// Switching filter with a slow response never shows rows from the previous filter
await page.getByRole('button', { name: 'Active queue', exact: true }).click(); await settle()
await page.route('**/orders/queue?status=received', async (route) => { await sleep(1200); await route.continue() })
await page.getByRole('button', { name: 'Received', exact: true }).click()
await sleep(300)
const midFlight = await page.locator('tbody tr td:nth-child(8)').allInnerTexts()
check('filter switch: no rows from the previous filter while loading', midFlight.every((c) => c === 'Received'), midFlight.join(',') || '(empty while loading)')
await settle(); await page.unroute('**/orders/queue?status=received')

// §8 empty state
await page.getByRole('button', { name: 'Preparing', exact: true }).click(); await settle()
while ((await page.getByRole('button', { name: /^Mark ready/ }).count()) > 0) {
  await page.getByRole('button', { name: /^Mark ready/ }).first().click(); await settle()
}
check('§8 empty state when the view has no orders', (await page.locator('tbody').innerText()).includes('No orders in this view'))
await page.screenshot({ path: `${OUT}/c-empty.png` })

// API unreachable -> visible error with Retry, then recovery
await page.getByRole('button', { name: 'Active queue', exact: true }).click(); await settle()
await page.route('**/orders/queue', (route) => route.fulfill({ status: 502, body: 'Bad gateway' }))
await page.getByRole('button', { name: 'Refresh' }).click()
const loadAlert = page.getByRole('alert')
await loadAlert.waitFor()
check('API down: error visible on screen', (await loadAlert.innerText()).includes('Could not load the queue'), (await loadAlert.innerText()).replace(/\s+/g, ' '))
await page.screenshot({ path: `${OUT}/d-api-down.png` })
await page.unroute('**/orders/queue')
await loadAlert.getByRole('button', { name: 'Retry' }).click(); await settle()
check('API back: Retry recovers and hides the error', (await page.getByRole('alert').count()) === 0 && (await rows().count()) > 0)

console.log(failures === 0 ? '\nALL CHECKS PASSED' : `\n${failures} CHECK(S) FAILED`)
await browser.close()
process.exit(failures ? 1 : 0)

