import { readFileSync } from 'node:fs'
import { createRequire } from 'node:module'
import { chromium } from 'playwright-core'

const require = createRequire(import.meta.url)
const axeSource = readFileSync(require.resolve('axe-core/axe.min.js'), 'utf8')
const OUT = process.argv[2]
const TAG = process.argv[3] ?? 'before'

const browser = await chromium.launch({ channel: 'msedge', headless: true })

// 1. axe-core accessibility audit (WCAG 2.x A/AA rules)
const page = await browser.newPage({ viewport: { width: 1400, height: 720 } })
await page.goto('http://localhost:5173')
await page.locator('tbody tr').first().waitFor()
await page.addScriptTag({ content: axeSource })
const axe = await page.evaluate(async () =>
  window.axe.run(document, { runOnly: ['wcag2a', 'wcag2aa', 'wcag21aa', 'best-practice'] }),
)
console.log(`axe violations: ${axe.violations.length}`)
for (const v of axe.violations) {
  console.log(`  [${v.impact}] ${v.id}: ${v.help} (${v.nodes.length} nodes)`)
  for (const n of v.nodes.slice(0, 3)) console.log(`      ${n.target.join(' ')} :: ${(n.any[0]?.message ?? n.failureSummary).split('\n')[0].slice(0, 140)}`)
}

// 2. Tab order: can the keyboard reach the filter and the row actions?
await page.keyboard.press('Tab')
const focusPath = []
for (let i = 0; i < 8; i++) {
  focusPath.push(await page.evaluate(() => (document.activeElement?.innerText || document.activeElement?.getAttribute('aria-label') || document.activeElement?.tagName).trim().slice(0, 25)))
  await page.keyboard.press('Tab')
}
console.log('tab order:', focusPath.join(' > '))

// 3. Narrower screens: does the page scroll horizontally? does the table fit?
for (const width of [1280, 1024, 768]) {
  const p = await browser.newPage({ viewport: { width, height: 768 } })
  await p.goto('http://localhost:5173')
  await p.locator('tbody tr').first().waitFor()
  const m = await p.evaluate(() => {
    const container = document.querySelector('.MuiTableContainer-root')
    return {
      pageScrollsX: document.documentElement.scrollWidth > window.innerWidth,
      tableOverflowX: container.scrollWidth - container.clientWidth,
      rowHeight: Math.round(document.querySelector('tbody tr').getBoundingClientRect().height),
      visibleRows: document.querySelectorAll('tbody tr').length,
    }
  })
  console.log(`width ${width}: ${JSON.stringify(m)}`)
  await p.screenshot({ path: `${OUT}/${TAG}-w${width}.png` })
  await p.close()
}
await browser.close()

