// Priority score for the kitchen queue (spec §5.1).
// Pure: everything it needs arrives as arguments, including `now`. No clock, no database.

const MS_PER_MINUTE = 60 * 1000;

// Every tunable number of the ranking lives here, so a product change to the
// ranking is a one-place edit (plus its test).
const PRIORITY_RULES = {
  typePoints: { dine_in: 30, takeout: 20, delivery: 10 },
  vipPoints: 20,
  wait: { stepMinutes: 10, pointsPerStep: 5, max: 40 },
  // Checked in order: the first bucket that covers the minutes left wins.
  // A promise further away than every bucket, or no promise at all, scores 0.
  promised: [
    { upToMinutes: 30, points: 25 },
    { upToMinutes: 60, points: 15 },
  ],
  complexity: { stepMinutes: 15, pointsPerStep: 5, max: 20 },
};

// Whole minutes from `from` to `to`, floored (9m50s -> 9). Negative when `to` is earlier.
function wholeMinutesBetween(from, to) {
  return Math.floor((new Date(to).getTime() - new Date(from).getTime()) / MS_PER_MINUTE);
}

// Clamped at 0 so an order with a placed_at slightly in the future (clock skew) is not penalized.
function minutesWaiting(placedAt, now) {
  return Math.max(0, wholeMinutesBetween(placedAt, now));
}

function totalPrepMinutes(items) {
  return items.reduce((sum, item) => sum + item.prep_time_minutes * item.quantity, 0);
}

// min(max, floor(value / step) * pointsPerStep) -- shared by wait time and complexity.
function steppedPoints(value, { stepMinutes, pointsPerStep, max }) {
  return Math.min(max, Math.floor(value / stepMinutes) * pointsPerStep);
}

// Uses whole floored minutes, like minutes_waiting, so the spec's "0-30" and "31-60"
// buckets have no gap (30m59s -> 30 -> top bucket). An overdue promise gives a negative
// number and lands in the top bucket: the spec only gives 0 to "more than 60 minutes away or null".
function promisedPoints(promisedAt, now, buckets) {
  if (promisedAt == null) return 0;
  const minutesLeft = wholeMinutesBetween(now, promisedAt);
  const bucket = buckets.find((b) => minutesLeft <= b.upToMinutes);
  return bucket ? bucket.points : 0;
}

function typePoints(type, pointsByType) {
  const points = pointsByType[type];
  // Fail loudly: a new order type without a weight is a bug, not a silent 0.
  if (points === undefined) throw new Error(`No priority weight for order type "${type}"`);
  return points;
}

/**
 * @param {object} order  { type, is_vip, placed_at, promised_at, items: [{ prep_time_minutes, quantity }] }
 * @param {Date} now      the moment the queue is computed (real clock in the app, frozen in tests)
 * @param {object} [rules] scoring weights; defaults to PRIORITY_RULES
 * @returns {number}
 */
function computeScore(order, now, rules = PRIORITY_RULES) {
  return (
    typePoints(order.type, rules.typePoints) +
    (order.is_vip ? rules.vipPoints : 0) +
    steppedPoints(minutesWaiting(order.placed_at, now), rules.wait) +
    promisedPoints(order.promised_at, now, rules.promised) +
    steppedPoints(totalPrepMinutes(order.items), rules.complexity)
  );
}

module.exports = { PRIORITY_RULES, computeScore, minutesWaiting };

