// The only module that talks to the API. Types mirror the JSON the API returns (snake_case,
// as in the spec). Score, order and allowed actions all come from the server.

export type OrderType = 'dine_in' | 'takeout' | 'delivery'
export type OrderStatus = 'received' | 'preparing' | 'ready' | 'picked_up' | 'cancelled'
export type OrderAction = 'start' | 'ready' | 'pickup' | 'cancel'

/** `active` = the API's default queue (received + preparing); the others map to `?status=`. */
export type QueueFilter = 'active' | 'received' | 'preparing'

export interface OrderItem {
  menu_item_id: number
  name: string
  prep_time_minutes: number
  quantity: number
}

export interface QueueOrder {
  id: number
  customer_name: string
  type: OrderType
  is_vip: boolean
  status: OrderStatus
  placed_at: string
  promised_at: string | null
  items: OrderItem[]
  score: number
  wait_minutes: number
  allowed_actions: OrderAction[]
}

export interface QueueResponse {
  generated_at: string
  orders: QueueOrder[]
}

/** An error the API reported (`code` is its stable error code) or a network failure. */
export class ApiError extends Error {
  readonly code: string
  readonly httpStatus: number

  constructor(code: string, message: string, httpStatus: number) {
    super(message)
    this.name = 'ApiError'
    this.code = code
    this.httpStatus = httpStatus
  }
}

/** Anything caught from an API call, as an ApiError the UI can display. */
export function toApiError(error: unknown): ApiError {
  return error instanceof ApiError ? error : new ApiError('UNEXPECTED_ERROR', String(error), 0)
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let response: Response
  try {
    response = await fetch(path, init)
  } catch {
    throw new ApiError('NETWORK_ERROR', 'Could not reach the API. Is it running?', 0)
  }

  const body = await response.json().catch(() => null)
  if (!response.ok) {
    const error = body?.error
    // No `{ error: { code } }` body means the answer did not come from our API
    // (e.g. the dev proxy reporting that nothing listens on port 4000).
    throw new ApiError(
      error?.code ?? 'UNEXPECTED_RESPONSE',
      error?.message ?? `No valid answer from the API (HTTP ${response.status}). Is it running on port 4000?`,
      response.status,
    )
  }
  return body as T
}

export function fetchQueue(filter: QueueFilter): Promise<QueueResponse> {
  const query = filter === 'active' ? '' : `?status=${filter}`
  return request<QueueResponse>(`/orders/queue${query}`)
}

export function transitionOrder(id: number, action: OrderAction): Promise<{ order: QueueOrder }> {
  return request<{ order: QueueOrder }>(`/orders/${id}/${action}`, { method: 'POST' })
}

