import { useState } from 'react'
import { Alert, AlertTitle, AppBar, Box, Button, Paper, Stack, Toolbar, Typography } from '@mui/material'
import { toApiError, transitionOrder } from './api/orders'
import type { ApiError, OrderAction, QueueFilter as Filter, QueueOrder } from './api/orders'
import { QueueFilter } from './components/QueueFilter'
import { QueueTable } from './components/QueueTable'
import { ACTION_LABEL, formatTime } from './format'
import { useQueue } from './hooks/useQueue'

interface ActionFailure {
  error: ApiError
  description: string // e.g. '"Start" on order #4 (Ben Turner)'
}

/** The Kitchen Display: the ranked active queue and the actions that move orders along. */
export default function App() {
  const [filter, setFilter] = useState<Filter>('active')
  const { orders, generatedAt, loading, error: loadError, reload } = useQueue(filter)
  const [pendingOrderId, setPendingOrderId] = useState<number | null>(null)
  const [actionFailure, setActionFailure] = useState<ActionFailure | null>(null)

  async function handleAction(order: QueueOrder, action: OrderAction) {
    setPendingOrderId(order.id)
    setActionFailure(null)
    try {
      await transitionOrder(order.id, action)
    } catch (err) {
      setActionFailure({
        error: toApiError(err),
        description: `"${ACTION_LABEL[action]}" on order #${order.id} (${order.customer_name})`,
      })
    } finally {
      setPendingOrderId(null)
      // Reload either way: after a rejection the row then shows the order's real current status.
      reload()
    }
  }

  return (
    <Box sx={{ height: '100vh', display: 'flex', flexDirection: 'column' }}>
      <AppBar position="static" elevation={0}>
        <Toolbar variant="dense" sx={{ gap: 2 }}>
          <Typography variant="h6" component="h1" sx={{ flexGrow: 1 }}>
            Kitchen Display
          </Typography>
          {generatedAt && (
            <Typography variant="body2" sx={{ opacity: 0.8 }}>
              Updated {formatTime(generatedAt, true)}
            </Typography>
          )}
          <Button color="inherit" variant="outlined" size="small" onClick={reload} disabled={loading}>
            Refresh
          </Button>
        </Toolbar>
      </AppBar>

      <Stack direction="row" alignItems="center" spacing={2} sx={{ px: 2, py: 1 }}>
        <QueueFilter value={filter} onChange={setFilter} />
        {orders && (
          <Typography variant="body2" color="text.secondary">
            {orders.length} {orders.length === 1 ? 'order' : 'orders'}
          </Typography>
        )}
      </Stack>

      <Stack spacing={1} sx={{ px: 2, pb: 1 }}>
        {actionFailure && (
          <Alert severity="error" onClose={() => setActionFailure(null)}>
            <AlertTitle>{actionFailure.description} was rejected</AlertTitle>
            {actionFailure.error.message} <code>{actionFailure.error.code}</code>
          </Alert>
        )}
        {loadError && (
          <Alert
            severity="error"
            action={
              <Button color="inherit" size="small" onClick={reload}>
                Retry
              </Button>
            }
          >
            <AlertTitle>Could not load the queue</AlertTitle>
            {loadError.message} <code>{loadError.code}</code>
          </Alert>
        )}
      </Stack>

      <Paper variant="outlined" sx={{ mx: 2, mb: 2, flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
        <QueueTable orders={orders} loading={loading} pendingOrderId={pendingOrderId} onAction={handleAction} />
      </Paper>
    </Box>
  )
}

