import {
  Chip,
  LinearProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material'
import type { TableCellProps } from '@mui/material'
import type { OrderAction, QueueFilter, QueueOrder } from '../api/orders'
import {
  EMPTY_QUEUE_MESSAGE,
  formatItems,
  formatMinutesUntil,
  formatTime,
  ORDER_TYPE_LABEL,
  STATUS_COLOR,
  STATUS_LABEL,
} from '../format'
import { OrderActions } from './OrderActions'

// Quantities are right-aligned with fixed-width digits so they line up for comparison.
const COLUMNS: { label: string; align: TableCellProps['align'] }[] = [
  { label: 'Score', align: 'right' },
  { label: 'Customer', align: 'left' },
  { label: 'Type', align: 'left' },
  { label: 'Items', align: 'left' },
  { label: 'Wait', align: 'right' },
  { label: 'Promised', align: 'left' },
  { label: 'VIP', align: 'left' },
  { label: 'Status', align: 'left' },
  { label: 'Actions', align: 'right' },
]

const numeric = { fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' } as const

// On narrow screens (a kitchen tablet) the table scrolls sideways; the actions column stays
// pinned to the right edge so the expeditor never loses the buttons.
const pinnedRight = { position: 'sticky', right: 0, bgcolor: 'background.paper' } as const

interface QueueTableProps {
  orders: QueueOrder[] | null // null = nothing loaded for this filter yet
  filter: QueueFilter
  loading: boolean
  pendingOrderId: number | null
  onAction: (order: QueueOrder, action: OrderAction) => void
}

/** Renders the orders exactly in the order the API returned them. No sorting, no scoring here. */
export function QueueTable({ orders, filter, loading, pendingOrderId, onAction }: QueueTableProps) {
  return (
    <TableContainer sx={{ flex: 1, minHeight: 0 }}>
      {/* Keeps its height while hidden so the table does not jump on every refresh. */}
      <LinearProgress sx={{ visibility: loading ? 'visible' : 'hidden' }} aria-hidden={!loading} />
      <Table size="small" stickyHeader aria-label="Kitchen queue">
        <TableHead>
          <TableRow>
            {COLUMNS.map((column) => (
              <TableCell
                key={column.label}
                align={column.align}
                // Above the sticky body cells; keeps the header's own background.
                sx={column.label === 'Actions' ? { ...pinnedRight, bgcolor: undefined, zIndex: 3 } : undefined}
              >
                {column.label}
              </TableCell>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {orders?.length === 0 && (
            <TableRow>
              <TableCell colSpan={COLUMNS.length} align="center" sx={{ py: 6 }}>
                <Typography color="text.secondary">{EMPTY_QUEUE_MESSAGE[filter]}</Typography>
              </TableCell>
            </TableRow>
          )}
          {orders?.map((order) => (
            <TableRow key={order.id} hover>
              <TableCell align="right" sx={{ ...numeric, fontWeight: 700 }}>
                {order.score}
              </TableCell>
              <TableCell>
                {order.customer_name}
                <Typography component="span" variant="caption" color="text.secondary" sx={{ ml: 1 }}>
                  #{order.id}
                </Typography>
              </TableCell>
              <TableCell>{ORDER_TYPE_LABEL[order.type]}</TableCell>
              <TableCell sx={{ maxWidth: 320 }}>{formatItems(order.items)}</TableCell>
              <TableCell align="right" sx={numeric}>
                {order.wait_minutes} min
              </TableCell>
              <TableCell sx={numeric}>
                <PromisedTime order={order} />
              </TableCell>
              <TableCell>{order.is_vip && <Chip label="VIP" color="secondary" size="small" />}</TableCell>
              <TableCell>
                <Chip label={STATUS_LABEL[order.status]} color={STATUS_COLOR[order.status]} size="small" />
              </TableCell>
              <TableCell align="right">
                <OrderActions order={order} disabled={pendingOrderId === order.id} onAction={onAction} />
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  )
}

/** "15:26 · in 20 min", or "15:26 · 5 min late" in the error color. Minutes come from the API. */
function PromisedTime({ order }: { order: QueueOrder }) {
  if (order.promised_at === null || order.minutes_until_promised === null) return <>—</>
  const late = order.minutes_until_promised < 0
  return (
    <>
      {formatTime(order.promised_at)}
      <Typography
        component="span"
        variant="caption"
        color={late ? 'error' : 'text.secondary'}
        sx={{ ml: 1, fontWeight: late ? 700 : 400 }}
      >
        {formatMinutesUntil(order.minutes_until_promised)}
      </Typography>
    </>
  )
}

import {
  Chip,
  LinearProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from '@mui/material'
