  { label: 'Customer', align: 'left' },
  { label: 'Type', align: 'left' },
  { label: 'Items', align: 'left' },
  { label: 'Wait', align: 'right' },
  { label: 'Promised', align: 'left' },
  { label: 'VIP', align: 'left' },
  { label: 'Status', align: 'left' },
  { label: 'Actions', align: 'right' },
