// Presentation only: labels, colors and text formatting. No business rules live here —
// which actions exist for an order, its score, its position and every time value come from the API.
import type { ChipProps } from '@mui/material'
import type { OrderAction, OrderItem, OrderStatus, OrderType, QueueFilter } from './api/orders'

export const ORDER_TYPE_LABEL: Record<OrderType, string> = {
  dine_in: 'Dine-in',
  takeout: 'Takeout',
  delivery: 'Delivery',
}

export const STATUS_LABEL: Record<OrderStatus, string> = {
  received: 'Received',
  preparing: 'Preparing',
  ready: 'Ready',
  picked_up: 'Picked up',
  cancelled: 'Cancelled',
}

export const STATUS_COLOR: Record<OrderStatus, ChipProps['color']> = {
  received: 'info',
  preparing: 'warning',
  ready: 'success',
  picked_up: 'default',
  cancelled: 'default',
}

export const ACTION_LABEL: Record<OrderAction, string> = {
  start: 'Start',
  ready: 'Mark ready',
  pickup: 'Picked up',
  cancel: 'Cancel',
}

export const EMPTY_QUEUE_MESSAGE: Record<QueueFilter, string> = {
  active: 'No active orders. The kitchen is clear.',
  received: 'No orders waiting to be started.',
  preparing: 'No orders in preparation.',
}

/** "2× Grilled Salmon, 1× Caesar Salad" */
export function formatItems(items: OrderItem[]): string {
  return items.map((item) => `${item.quantity}× ${item.name}`).join(', ')
}

/** Local wall-clock time, e.g. "14:35" (or "14:35:08" with seconds). */
export function formatTime(isoTimestamp: string, withSeconds = false): string {
  return new Date(isoTimestamp).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
    ...(withSeconds && { second: '2-digit' }),
  })
}

/** "45 min", "2 h", "2 h 59 min" */
function formatDuration(minutes: number): string {
  if (minutes < 60) return `${minutes} min`
  const hours = Math.floor(minutes / 60)
  const rest = minutes % 60
  return rest === 0 ? `${hours} h` : `${hours} h ${rest} min`
}

/** The API's minutes_until_promised as text: "in 20 min", "in 2 h 59 min", "due now", "5 min late". */
export function formatMinutesUntil(minutes: number): string {
  if (minutes > 0) return `in ${formatDuration(minutes)}`
  if (minutes === 0) return 'due now'
  return `${formatDuration(-minutes)} late`
}

