import { Box, Stack, Typography } from '@mui/material'
import CheckCircleIcon from '@mui/icons-material/CheckCircle'
import RadioButtonCheckedIcon from '@mui/icons-material/RadioButtonChecked'
import RadioButtonUncheckedIcon from '@mui/icons-material/RadioButtonUnchecked'
import type { OrderStatus } from '../api/orders'
import { KITCHEN_STEPS, STATUS_COLOR, STATUS_LABEL } from '../format'

/**
 * "✓ Received — ● Preparing — ○ Ready": done steps are checked, the current one is highlighted.
 * Shows where the order is in its journey; it does not decide what may happen next.
 */
export function StatusProgress({ status }: { status: OrderStatus }) {
  const current = KITCHEN_STEPS.indexOf(status)

  return (
    <Stack direction="row" alignItems="center" spacing={0.5} aria-label={`Status: ${STATUS_LABEL[status]}`}>
      {KITCHEN_STEPS.map((step, index) => {
        const done = index < current
        const isCurrent = index === current
        const color = isCurrent ? `${STATUS_COLOR[step]}.main` : done ? 'success.main' : 'text.disabled'
        const Icon = done ? CheckCircleIcon : isCurrent ? RadioButtonCheckedIcon : RadioButtonUncheckedIcon
        return (
          <Stack key={step} direction="row" alignItems="center" spacing={0.5}>
            {index > 0 && <Box sx={{ width: 10, borderTop: 1, borderColor: done || isCurrent ? 'success.main' : 'divider' }} />}
            <Icon sx={{ fontSize: 16, color }} aria-hidden />
            <Typography
              variant="caption"
              sx={{ color: isCurrent ? color : done ? 'text.primary' : 'text.secondary', fontWeight: isCurrent ? 700 : 400 }}
            >
              {STATUS_LABEL[step]}
            </Typography>
          </Stack>
        )
      })}
    </Stack>
  )
}

