import { Button, Stack } from '@mui/material'
import type { OrderAction, QueueOrder } from '../api/orders'
import { ACTION_LABEL } from '../format'

interface OrderActionsProps {
  order: QueueOrder
  disabled: boolean
  onAction: (order: QueueOrder, action: OrderAction) => void
}

/**
 * Renders exactly the actions the API lists in `allowed_actions` — the state machine lives
 * on the server, so a status change there needs no change here. The step forward is the
 * primary button; cancelling is a quieter, secondary one.
 */
export function OrderActions({ order, disabled, onAction }: OrderActionsProps) {
  const forward = order.allowed_actions.filter((action) => action !== 'cancel')
  const canCancel = order.allowed_actions.includes('cancel')

  return (
    <Stack direction="row" spacing={1} justifyContent="flex-end" alignItems="center">
      {forward.map((action) => (
        <Button
          key={action}
          size="small"
          variant="contained"
          disabled={disabled}
          onClick={() => onAction(order, action)}
          aria-label={`${ACTION_LABEL[action]}: order ${order.id}`}
          sx={{ whiteSpace: 'nowrap' }}
        >
          {ACTION_LABEL[action]}
        </Button>
      ))}
      {canCancel && (
        <Button
          size="small"
          color="error"
          disabled={disabled}
          onClick={() => onAction(order, 'cancel')}
          aria-label={`${ACTION_LABEL.cancel}: order ${order.id}`}
        >
          {ACTION_LABEL.cancel}
        </Button>
      )}
    </Stack>
  )
}

