import {
  Box,
  Chip,
  LinearProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tooltip,
  Typography,
} from '@mui/material'
import type { TableCellProps } from '@mui/material'
import DeliveryDiningOutlinedIcon from '@mui/icons-material/DeliveryDiningOutlined'
import RestaurantOutlinedIcon from '@mui/icons-material/RestaurantOutlined'
import ShoppingBagOutlinedIcon from '@mui/icons-material/ShoppingBagOutlined'
import type { OrderAction, OrderType, QueueFilter, QueueOrder } from '../api/orders'
import {
  EMPTY_QUEUE_MESSAGE,
  formatDuration,
  formatMinutesUntil,
  formatTime,
  ORDER_TYPE_HINT,
  ORDER_TYPE_LABEL,
} from '../format'
import { OrderActions } from './OrderActions'
import { StatusProgress } from './StatusProgress'

const COLUMNS: { label: string; align: TableCellProps['align']; help?: string }[] = [
  {
    label: 'Priority',
    align: 'left',
    help: 'Position in the queue and the priority score calculated by the server. Work from the top.',
  },
  { label: 'Order', align: 'left' },
  { label: 'VIP', align: 'left' },
  { label: 'Type', align: 'left', help: 'Where the food goes: eaten here, picked up, or delivered.' },
  { label: 'Items', align: 'left' },
  { label: 'Waiting', align: 'right', help: 'Time since the order was placed.' },
  { label: 'Promised', align: 'left', help: 'Time promised to the customer (takeout and delivery).' },
  { label: 'Status', align: 'left' },
  { label: 'Next step', align: 'right' },
]

const ORDER_TYPE_ICON: Record<OrderType, typeof RestaurantOutlinedIcon> = {
  dine_in: RestaurantOutlinedIcon,
  takeout: ShoppingBagOutlinedIcon,
  delivery: DeliveryDiningOutlinedIcon,
}

const numeric = { fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' } as const

// On narrow screens (a kitchen tablet) the table scrolls sideways; the actions column stays
// pinned to the right edge so the expeditor never loses the buttons.
const pinnedRight = { position: 'sticky', right: 0, bgcolor: 'background.paper' } as const

interface QueueTableProps {
  orders: QueueOrder[] | null // null = nothing loaded for this filter yet
  filter: QueueFilter
  loading: boolean
  pendingOrderId: number | null
  onAction: (order: QueueOrder, action: OrderAction) => void
}

/**
 * Renders the orders exactly in the order the API returned them: position 1 is simply the
 * first row. No sorting, no scoring here.
 */
export function QueueTable({ orders, filter, loading, pendingOrderId, onAction }: QueueTableProps) {
  return (
    <TableContainer sx={{ flex: 1, minHeight: 0 }}>
      {/* Keeps its height while hidden so the table does not jump on every refresh. */}
      <LinearProgress sx={{ visibility: loading ? 'visible' : 'hidden' }} aria-hidden={!loading} />
      <Table size="small" stickyHeader aria-label="Kitchen queue">
        <TableHead>
          <TableRow>
            {COLUMNS.map((column) => (
              <TableCell
                key={column.label}
                align={column.align}
                // Above the sticky body cells; keeps the header's own background.
                sx={column.label === 'Next step' ? { ...pinnedRight, bgcolor: undefined, zIndex: 3 } : undefined}
              >
                {column.help ? (
                  <Tooltip title={column.help}>
