import { chromium } from 'playwright-core'

const OUT = process.argv[2]
const BASE = 'http://localhost:5173'
let failures = 0
const check = (label, ok, extra = '') => {
  if (!ok) failures++
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${extra ? `  — ${extra}` : ''}`)
}
const api = async (path, init) => {
  const res = await fetch(`${BASE}${path}`, init)
  return { status: res.status, body: await res.json() }
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms))

const browser = await chromium.launch({ channel: 'msedge', headless: true })
const page = await browser.newPage({ viewport: { width: 1440, height: 760 } })
const rows = () => page.locator('tbody tr')
// Column 2 ("Order") starts with "#<id>"
const rowOf = (id) => page.locator('tbody tr', { has: page.locator('td:nth-child(2) p:first-child', { hasText: new RegExp(`^#${id}$`) }) })
const statusOf = async (row) => (await row.locator('[aria-label^="Status: "]').getAttribute('aria-label')).replace('Status: ', '')
const settle = () =>
  page.waitForFunction(() => getComputedStyle(document.querySelector('.MuiLinearProgress-root')).visibility === 'hidden')
const LABEL = { start: 'Start preparing', ready: 'Mark as ready', pickup: 'Mark picked up', cancel: 'Cancel' }

await page.goto(BASE)
await settle()

// §8 table content
const headers = await page.locator('thead th').allInnerTexts()
check('§8 table has priority/score, order+customer, VIP, type, items, waiting, promised, status',
  ['Priority', 'Order', 'VIP', 'Type', 'Items', 'Waiting', 'Promised', 'Status'].every((h) => headers.includes(h)), headers.join('|'))

let queue = (await api('/orders/queue')).body.orders
const uiIds = (await page.locator('tbody tr td:nth-child(2) p:first-child').allInnerTexts()).map((t) => Number(t.replace('#', '')))
check('§8 rows in exactly the API order', JSON.stringify(uiIds) === JSON.stringify(queue.map((o) => o.id)), uiIds.join(','))
const uiScores = (await page.locator('tbody tr td:nth-child(1)').allInnerTexts()).map((t) => Number(t.match(/score (\d+)/)[1]))
check('§7/§8 score shown = score from API', JSON.stringify(uiScores) === JSON.stringify(queue.map((o) => o.score)), uiScores.join(','))
const positions = (await page.locator('tbody tr td:nth-child(1)').allInnerTexts()).map((t) => Number(t.split(/\s/)[0]))
check('position column is 1..n (just the API order)', positions.every((p, i) => p === i + 1))
check('"Next up" marks only the first row', (await page.getByText('Next up', { exact: true }).count()) === 1 &&
  (await rows().first().innerText()).includes('Next up'))
check('§5 default queue only received/preparing', queue.every((o) => ['received', 'preparing'].includes(o.status)))
check('§9.5 seed tie broken by promised_at (Chloe before David, both 25)',
  queue.findIndex((o) => o.customer_name === 'Chloe Davis') < queue.findIndex((o) => o.customer_name === 'David Reed'))
check('§8 VIP badge on VIP orders only',
  (await page.locator('tbody .MuiChip-root', { hasText: /^VIP$/ }).count()) === queue.filter((o) => o.is_vip).length)
const felix = queue.find((o) => o.customer_name === 'Felix Carter')
check('order type with its meaning', (await rowOf(felix.id).locator('td:nth-child(4)').innerText()).includes('goes out with a courier'))
check('items listed one per line', (await rowOf(queue.find((o) => o.customer_name === 'Emma Brooks').id).locator('td:nth-child(5) li').count()) === 3)
const promisedText = (await rowOf(felix.id).locator('td:nth-child(7)').innerText()).replace(/\s+/g, ' ')
check('promised = time + API minutes', promisedText.includes(`in ${felix.minutes_until_promised} min`), promisedText)
check('status shown as progress with the current step', (await statusOf(rowOf(felix.id))) === 'Received')

// §8 only the valid action per row; cancel only for received
let buttonsOk = true
for (const o of queue) {
  const labels = (await rowOf(o.id).getByRole('button').allInnerTexts()).map((l) => l.toLowerCase())
  const expected = [...o.allowed_actions.filter((a) => a !== 'cancel'), ...o.allowed_actions.filter((a) => a === 'cancel')].map((a) => LABEL[a].toLowerCase())
  if (JSON.stringify(labels) !== JSON.stringify(expected)) buttonsOk = false
  if (labels.includes('cancel') && o.status !== 'received') buttonsOk = false
}
check('§8 each row shows only its valid actions; Cancel only on received', buttonsOk)

// §8 cancel (with confirmation)
const toCancel = queue.find((o) => o.customer_name === 'David Reed')
await rowOf(toCancel.id).getByRole('button', { name: /^Cancel/ }).click()
const dialog = page.getByRole('dialog')
await dialog.waitFor()
check('cancel asks for confirmation (irreversible action)', (await dialog.innerText()).includes(`#${toCancel.id}`))
await dialog.getByRole('button', { name: 'Keep order' }).click()
await dialog.waitFor({ state: 'hidden' })
check('"Keep order" does not cancel', (await rowOf(toCancel.id).count()) === 1)
await rowOf(toCancel.id).getByRole('button', { name: /^Cancel/ }).click()
await page.getByRole('dialog').getByRole('button', { name: 'Cancel order' }).click()
await settle()
check('§8 cancel: order leaves the active queue', (await rowOf(toCancel.id).count()) === 0)
const snack = page.locator('.MuiSnackbar-root')
await snack.waitFor()
check('feedback says what happened and where the order went', (await snack.innerText()).includes('cancelled and removed'), await snack.innerText())

// §6 lifecycle via UI
const toStart = (await api('/orders/queue')).body.orders.find((o) => o.status === 'received')
await rowOf(toStart.id).getByRole('button', { name: /^Start preparing/ }).click()
await settle()
check('§6 start: progress moves to Preparing', (await statusOf(rowOf(toStart.id))) === 'Preparing')
await rowOf(toStart.id).getByRole('button', { name: /^Mark as ready/ }).click()
await settle()
check('§5 ready order leaves the active queue', (await rowOf(toStart.id).count()) === 0)
await sleep(200)
check('feedback explains the ready order left the queue', (await snack.innerText()).includes('waiting for pickup'), await snack.innerText())

// §6 server enforcement when the API is called directly
const preparing = (await api('/orders/queue?status=preparing')).body.orders[0]
const direct = await api(`/orders/${preparing.id}/start`, { method: 'POST' })
check('§6 direct API call: start on preparing -> 409 INVALID_TRANSITION', direct.status === 409 && direct.body.error.code === 'INVALID_TRANSITION')
check('§6 direct API call: skipping a step -> 409', (await api(`/orders/${preparing.id}/pickup`, { method: 'POST' })).status === 409)
const pickedUp = await api(`/orders/${toStart.id}/pickup`, { method: 'POST' })
check('§6 ready -> picked_up succeeds', pickedUp.status === 200 && pickedUp.body.order.status === 'picked_up')
check('§6 terminal: picked_up cannot move again -> 409', (await api(`/orders/${toStart.id}/pickup`, { method: 'POST' })).status === 409)

// §8 rejected transition is visible on screen
const victim = (await api('/orders/queue?status=received')).body.orders[0]
await page.reload(); await settle()
await api(`/orders/${victim.id}/start`, { method: 'POST' })
await rowOf(victim.id).getByRole('button', { name: /^Start preparing/ }).click()
const alert = page.locator('.MuiAlert-root')
await alert.waitFor()
const alertText = (await alert.innerText()).replace(/\s+/g, ' ')
check('§8 API rejection visible on screen with its code', alertText.includes('INVALID_TRANSITION'), alertText)
await settle()
check('     ...and the row then shows the real status', (await statusOf(rowOf(victim.id))) === 'Preparing')
await page.screenshot({ path: `${OUT}/v2-rejected.png` })
await alert.getByRole('button', { name: 'Close' }).click()

// §8 filters
for (const [name, status] of [['Received', 'received'], ['Preparing', 'preparing']]) {
  await page.getByRole('button', { name, exact: true }).click()
  await settle()
  const statuses = await Promise.all((await rows().all()).map(statusOf))
  const expectedCount = (await api(`/orders/queue?status=${status}`)).body.orders.length
  check(`§8 filter "${name}" shows only ${status} orders`, statuses.length === expectedCount && statuses.every((s) => s === name), statuses.join(','))
}

// Switching filter with a slow response never shows rows from the previous filter
await page.getByRole('button', { name: 'Active queue', exact: true }).click(); await settle()
await page.route('**/orders/queue?status=received', async (route) => { await sleep(1200); await route.continue() })
await page.getByRole('button', { name: 'Received', exact: true }).click()
await sleep(300)
const midFlight = await Promise.all((await rows().all()).map(async (r) => ((await r.locator('[aria-label^="Status: "]').count()) ? statusOf(r) : 'n/a')))
check('filter switch: no rows from the previous filter while loading', midFlight.every((s) => s === 'Received' || s === 'n/a'), midFlight.join(',') || '(empty)')
await settle(); await page.unroute('**/orders/queue?status=received')

// §8 empty state
await page.getByRole('button', { name: 'Preparing', exact: true }).click(); await settle()
while ((await page.getByRole('button', { name: /^Mark as ready/ }).count()) > 0) {
  await page.getByRole('button', { name: /^Mark as ready/ }).first().click(); await settle()
}
check('§8 empty state when the view has no orders', (await page.locator('tbody').innerText()).includes('No orders in preparation'))

// API unreachable -> visible error with Retry, then recovery
await page.getByRole('button', { name: 'Active queue', exact: true }).click(); await settle()
await page.route('**/orders/queue', (route) => route.fulfill({ status: 502, body: 'Bad gateway' }))
await page.getByRole('button', { name: 'Refresh' }).click()
const loadAlert = page.locator('.MuiAlert-root', { hasText: 'Could not load' })
await loadAlert.waitFor()
check('API down: error visible on screen', true, (await loadAlert.innerText()).replace(/\s+/g, ' '))
await page.unroute('**/orders/queue')
await loadAlert.getByRole('button', { name: 'Retry' }).click(); await settle()
check('API back: Retry recovers and hides the error', (await page.locator('.MuiAlert-root').count()) === 0 && (await rows().count()) > 0)

console.log(failures === 0 ? '\nALL CHECKS PASSED' : `\n${failures} CHECK(S) FAILED`)
await browser.close()
process.exit(failures ? 1 : 0)

