        'orders',
        'status_changed_at',
        { type: Sequelize.DATE, allowNull: false, defaultValue: Sequelize.fn('now') },
        { transaction },
      );
    });
  },

  async down(queryInterface) {
    await queryInterface.removeColumn('orders', 'status_changed_at');
  },
};

