1	// Use cases for the expeditor screen. Applies the pure rules (queue, transitions) to data
2	// loaded through the repository. Knows nothing about HTTP.
3	const { AppError } = require('../errors');
4	const repository = require('../repositories/orders.repository');
5	const { resolveQueueStatuses, rankQueue, withComputedFields } = require('./queue');
6	const { resolveTransition } = require('./transitions');
7	
8	async function getQueue({ status, now }) {
9	  const statuses = resolveQueueStatuses(status);
10	  const orders = await repository.findOrdersByStatuses(statuses);
11	  return rankQueue(orders, now);
12	}
13	
14	const orderNotFound = (id) => new AppError('ORDER_NOT_FOUND', `Order ${id} does not exist.`, { id });
15	
16	async function transitionOrder({ id, action, now }) {
17	  const order = await repository.findOrderById(id);
18	  if (!order) throw orderNotFound(id);
19	
20	  const nextStatus = resolveTransition(order.status, action); // throws INVALID_TRANSITION
21	
