import { useEffect, useState } from 'react'
import { fetchOrders, toApiError } from '../api/orders'
import type { ApiError, OrdersResponse } from '../api/orders'

interface Result {
  path: string // the list `data` was loaded from
  requestKey: string // the request this result answers
  data: OrdersResponse | null // last successful response, kept while refreshing or after an error
  error: ApiError | null
}

/**
 * Loads the order list at `path` (null = nothing to load) and loads it again whenever
 * `refreshTick` changes.
 */
export function useOrders(path: string | null, refreshTick: number) {
  const [result, setResult] = useState<Result | null>(null)

  // Identifies the request the screen currently wants. `loading` is derived from it instead of
  // being stored, so the effect below never has to set state synchronously.
  const requestKey = `${path}#${refreshTick}`

  useEffect(() => {
    if (path === null) return

    // Set by the cleanup when the path changes or a newer refresh starts before this request
    // finishes: a slower, older response must not overwrite a newer one.
    let ignore = false

    fetchOrders(path).then(
      (data) => {
        if (!ignore) setResult({ path, requestKey, data, error: null })
      },
      (error: unknown) => {
        if (ignore) return
        setResult((previous) => ({
          path,
          requestKey,
          data: previous?.path === path ? previous.data : null,
          error: toApiError(error),
        }))
      },
    )

    return () => {
      ignore = true
    }
  }, [path, requestKey])

  // Rows loaded from another list (e.g. the previous filter) are never shown: they would
  // contradict what is selected. A refresh of the same list keeps its rows on screen.
  const current = path !== null && result?.path === path ? result : null

  return {
    orders: current?.data?.orders ?? null,
    generatedAt: current?.data?.generated_at ?? null,
    loading: path !== null && result?.requestKey !== requestKey,
    error: current?.error ?? null,
  }
}

