import { useCallback, useEffect, useState } from 'react'

/**
 * A counter that goes up every `intervalMs` (and on `refresh()`), so lists keyed on it reload.
 * Waiting times and scores are computed by the API at request time, so reloading is what
 * makes them advance on screen. This is plain periodic polling, not a push channel.
 *
 * Paused while the tab is hidden (nobody is looking, and browsers throttle hidden timers
 * anyway); refreshes immediately when the screen becomes visible again.
 */
export function useAutoRefresh(intervalMs: number) {
  const [tick, setTick] = useState(0)
  const refresh = useCallback(() => setTick((count) => count + 1), [])

  useEffect(() => {
    let timer: number | undefined
    const start = () => {
      timer = window.setInterval(refresh, intervalMs)
    }
    const stop = () => window.clearInterval(timer)
    const onVisibilityChange = () => {
      stop()
      if (!document.hidden) {
        refresh()
        start()
      }
    }

    if (!document.hidden) start()
    document.addEventListener('visibilitychange', onVisibilityChange)
    return () => {
      stop()
      document.removeEventListener('visibilitychange', onVisibilityChange)
    }
  }, [intervalMs, refresh])

  return { tick, refresh }
}

