import { Box, Chip, Stack, Typography } from '@mui/material'
import DeliveryDiningOutlinedIcon from '@mui/icons-material/DeliveryDiningOutlined'
import RestaurantOutlinedIcon from '@mui/icons-material/RestaurantOutlined'
import ShoppingBagOutlinedIcon from '@mui/icons-material/ShoppingBagOutlined'
import StarRoundedIcon from '@mui/icons-material/StarRounded'
import type { Order, OrderType } from '../api/orders'
import { formatDuration, formatMinutesUntil, formatTime, ORDER_TYPE_HINT, ORDER_TYPE_LABEL } from '../format'

export const numeric = { fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' } as const

const ORDER_TYPE_ICON: Record<OrderType, typeof RestaurantOutlinedIcon> = {
  dine_in: RestaurantOutlinedIcon,
  takeout: ShoppingBagOutlinedIcon,
  delivery: DeliveryDiningOutlinedIcon,
}

/** "#12" over the customer's name. */
export function OrderCell({ order }: { order: Order }) {
  return (
    <Box sx={{ whiteSpace: 'nowrap' }}>
      <Typography sx={{ fontWeight: 700 }}>#{order.id}</Typography>
      <Typography variant="body2" color="text.secondary">
        {order.customer_name}
      </Typography>
    </Box>
  )
}

/** A star badge for VIP customers; a quiet dash otherwise, so the column always reads clearly. */
export function VipCell({ isVip }: { isVip: boolean }) {
  return isVip ? (
    <Chip icon={<StarRoundedIcon />} label="VIP" color="secondary" size="small" />
  ) : (
    <Typography variant="body2" color="text.disabled" aria-label="Not VIP">
      —
    </Typography>
  )
}

/** Icon + "Delivery" over "goes out with a courier". */
export function TypeCell({ type }: { type: OrderType }) {
  const Icon = ORDER_TYPE_ICON[type]
  return (
    <>
      <Stack direction="row" alignItems="center" spacing={0.75}>
        <Icon sx={{ fontSize: 18, color: 'text.secondary' }} aria-hidden />
        <Typography variant="body2" sx={{ fontWeight: 500 }}>
          {ORDER_TYPE_LABEL[type]}
        </Typography>
      </Stack>
      <Typography variant="caption" color="text.secondary">
        {ORDER_TYPE_HINT[type]}
      </Typography>
    </>
  )
}

/** One dish per line, quantity first: "2× Grilled Salmon". */
export function ItemsCell({ order }: { order: Order }) {
  return (
    <Box component="ul" sx={{ m: 0, p: 0, listStyle: 'none' }}>
      {order.items.map((item) => (
        <li key={item.menu_item_id}>
          <Box component="span" sx={{ fontWeight: 700, ...numeric }}>
            {item.quantity}×
          </Box>{' '}
          {item.name}
        </li>
      ))}
    </Box>
  )
}

/** A duration from the API over a caption, e.g. "1 h 35 min" / "since 15:13". */
export function DurationCell({ minutes, caption }: { minutes: number; caption: string }) {
  return (
    <>
      <Typography sx={{ ...numeric, fontWeight: 600 }}>{formatDuration(minutes)}</Typography>
      <Typography variant="caption" color="text.secondary" sx={numeric}>
        {caption}
      </Typography>
    </>
  )
}

/** "17:08" over "in 19 min", or "5 min late" in the error color. Minutes come from the API. */
export function PromisedCell({ order }: { order: Order }) {
  if (order.promised_at === null || order.minutes_until_promised === null) {
    return (
      <Typography variant="body2" color="text.disabled">
        No promise
      </Typography>
    )
  }
  const late = order.minutes_until_promised < 0
  return (
    <>
      <Typography sx={{ ...numeric, fontWeight: 600 }}>{formatTime(order.promised_at)}</Typography>
      <Typography variant="caption" color={late ? 'error' : 'text.secondary'} sx={{ fontWeight: late ? 700 : 400 }}>
        {formatMinutesUntil(order.minutes_until_promised)}
      </Typography>
    </>
  )
}

