import type { ReactNode } from 'react'
import {
  Box,
  LinearProgress,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tooltip,
  Typography,
} from '@mui/material'
import type { TableCellProps } from '@mui/material'

export interface Column {
  label: string
  align?: TableCellProps['align']
  help?: string // shown as a tooltip on the header
}

// On narrow screens (a kitchen tablet) the table scrolls sideways; the last column (actions)
// stays pinned to the right edge so the expeditor never loses the buttons. The soft shadow
// shows that other columns scroll underneath it.
export const pinnedRight = {
  position: 'sticky',
  right: 0,
  bgcolor: 'background.paper',
  boxShadow: '-8px 0 8px -8px rgba(0, 0, 0, 0.2)',
} as const

interface OrdersTableShellProps {
  label: string // accessible name of the table
  columns: Column[]
  pinLastColumn?: boolean
  loading: boolean
  isEmpty: boolean
  emptyMessage: string
  children: ReactNode // the body rows
}

/** The frame every order table shares: header with help tooltips, loading bar, empty state. */
export function OrdersTableShell({
  label,
  columns,
  pinLastColumn = false,
  loading,
  isEmpty,
  emptyMessage,
  children,
}: OrdersTableShellProps) {
  return (
    <TableContainer sx={{ flex: 1, minHeight: 0 }}>
      {/* Keeps its height while hidden so the table does not jump on every refresh. */}
      <LinearProgress sx={{ visibility: loading ? 'visible' : 'hidden', height: 2 }} aria-hidden={!loading} />
      <Table size="small" stickyHeader aria-label={label}>
        <TableHead>
          <TableRow>
            {columns.map((column, index) => (
              <TableCell
                key={column.label}
                align={column.align}
                // Above the sticky body cells; keeps the header's own background.
                sx={pinLastColumn && index === columns.length - 1 ? { ...pinnedRight, bgcolor: undefined, zIndex: 3 } : undefined}
              >
                {column.help ? (
                  <Tooltip title={column.help}>
                    <Box component="span" sx={{ borderBottom: '1px dotted', cursor: 'help' }}>
                      {column.label}
                    </Box>
                  </Tooltip>
                ) : (
                  column.label
                )}
              </TableCell>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {isEmpty && (
            <TableRow>
              <TableCell colSpan={columns.length} align="center" sx={{ py: 8 }}>
                <Typography color="text.secondary">{emptyMessage}</Typography>
              </TableCell>
            </TableRow>
          )}
          {children}
        </TableBody>
      </Table>
    </TableContainer>
  )
}

/** Row style shared by the tables: a solid hover color on every cell, so the pinned cell matches. */
export const rowSx = { '&:hover > td': { bgcolor: 'grey.50' } } as const

