import {
  Box,
  Chip,
  LinearProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tooltip,
  Typography,
} from '@mui/material'
import type { TableCellProps } from '@mui/material'
import DeliveryDiningOutlinedIcon from '@mui/icons-material/DeliveryDiningOutlined'
import RestaurantOutlinedIcon from '@mui/icons-material/RestaurantOutlined'
import ShoppingBagOutlinedIcon from '@mui/icons-material/ShoppingBagOutlined'
import type { OrderAction, OrderType, QueueFilter, QueueOrder } from '../api/orders'
import {
  EMPTY_QUEUE_MESSAGE,
  formatDuration,
  formatMinutesUntil,
  formatTime,
  ORDER_TYPE_HINT,
  ORDER_TYPE_LABEL,
} from '../format'
import { OrderActions } from './OrderActions'
import { StatusProgress } from './StatusProgress'

const COLUMNS: { label: string; align: TableCellProps['align']; help?: string }[] = [
  {
    label: 'Priority',
    align: 'left',
    help: 'Position in the queue and the priority score calculated by the server. Work from the top.',
  },
  { label: 'Order', align: 'left', help: 'Order number and customer. VIP customers are marked.' },
  { label: 'Type', align: 'left', help: 'Where the food goes: eaten here, picked up, or delivered.' },
  { label: 'Items', align: 'left' },
  { label: 'Waiting', align: 'right', help: 'Time since the order was placed.' },
  { label: 'Promised', align: 'left', help: 'Time promised to the customer (takeout and delivery).' },
  { label: 'Status', align: 'left' },
  { label: 'Next step', align: 'right' },
]

const ORDER_TYPE_ICON: Record<OrderType, typeof RestaurantOutlinedIcon> = {
  dine_in: RestaurantOutlinedIcon,
  takeout: ShoppingBagOutlinedIcon,
  delivery: DeliveryDiningOutlinedIcon,
}

const numeric = { fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' } as const

// On narrow screens (a kitchen tablet) the table scrolls sideways; the actions column stays
// pinned to the right edge so the expeditor never loses the buttons. The soft shadow shows
// that other columns can scroll underneath it.
const pinnedRight = {
  position: 'sticky',
  right: 0,
  bgcolor: 'background.paper',
  boxShadow: '-8px 0 8px -8px rgba(0, 0, 0, 0.25)',
} as const

interface QueueTableProps {
  orders: QueueOrder[] | null // null = nothing loaded for this filter yet
  filter: QueueFilter
  loading: boolean
  pendingOrderId: number | null
  onAction: (order: QueueOrder, action: OrderAction) => void
}

/**
 * Renders the orders exactly in the order the API returned them: position 1 is simply the
 * first row. No sorting, no scoring here.
 */
export function QueueTable({ orders, filter, loading, pendingOrderId, onAction }: QueueTableProps) {
  return (
    <TableContainer sx={{ flex: 1, minHeight: 0 }}>
      {/* Keeps its height while hidden so the table does not jump on every refresh. */}
      <LinearProgress sx={{ visibility: loading ? 'visible' : 'hidden' }} aria-hidden={!loading} />
      <Table size="small" stickyHeader aria-label="Kitchen queue">
        <TableHead>
          <TableRow>
            {COLUMNS.map((column) => (
              <TableCell
                key={column.label}
                align={column.align}
                // Above the sticky body cells; keeps the header's own background.
                sx={column.label === 'Next step' ? { ...pinnedRight, bgcolor: undefined, zIndex: 3 } : undefined}
              >
                {column.help ? (
                  <Tooltip title={column.help}>
                    <Box component="span" sx={{ borderBottom: '1px dotted', cursor: 'help' }}>
                      {column.label}
                    </Box>
                  </Tooltip>
                ) : (
                  column.label
                )}
              </TableCell>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {orders?.length === 0 && (
            <TableRow>
              <TableCell colSpan={COLUMNS.length} align="center" sx={{ py: 6 }}>
                <Typography color="text.secondary">{EMPTY_QUEUE_MESSAGE[filter]}</Typography>
              </TableCell>
            </TableRow>
          )}
          {orders?.map((order, index) => (
            <QueueRow
              key={order.id}
              order={order}
              position={index + 1}
              pending={pendingOrderId === order.id}
              onAction={onAction}
            />
          ))}
        </TableBody>
      </Table>
    </TableContainer>
  )
}

interface QueueRowProps {
  order: QueueOrder
  position: number
  pending: boolean
  onAction: (order: QueueOrder, action: OrderAction) => void
}

function QueueRow({ order, position, pending, onAction }: QueueRowProps) {
  const isNext = position === 1
  const TypeIcon = ORDER_TYPE_ICON[order.type]

  return (
    <TableRow
      sx={{
        // Solid hover color on every cell, so the pinned actions cell highlights with its row.
        '&:hover > td': { bgcolor: 'grey.100' },
        // The first row is what the kitchen should work on next: marked with an accent bar.
        ...(isNext && { '& > td:first-of-type': { boxShadow: (t) => `inset 4px 0 0 ${t.palette.primary.main}` } }),
      }}
    >
      <TableCell sx={{ whiteSpace: 'nowrap' }}>
        <Stack direction="row" alignItems="baseline" spacing={1}>
          <Typography component="span" sx={{ ...numeric, fontWeight: 700, fontSize: 18, minWidth: 20 }}>
            {position}
          </Typography>
          <Typography component="span" variant="caption" color="text.secondary" sx={numeric}>
            score {order.score}
          </Typography>
        </Stack>
        {isNext && <Chip label="Next up" color="primary" size="small" sx={{ mt: 0.5 }} />}
      </TableCell>

      <TableCell sx={{ whiteSpace: 'nowrap' }}>
        <Typography sx={{ fontWeight: 700 }}>#{order.id}</Typography>
        <Stack direction="row" alignItems="center" spacing={0.75}>
          <Typography variant="body2">{order.customer_name}</Typography>
          {order.is_vip && <Chip label="VIP" color="secondary" size="small" />}
        </Stack>
      </TableCell>

      <TableCell sx={{ minWidth: 120 }}>
        <Stack direction="row" alignItems="center" spacing={0.75}>
          <TypeIcon sx={{ fontSize: 18, color: 'text.secondary' }} aria-hidden />
          <Typography variant="body2">{ORDER_TYPE_LABEL[order.type]}</Typography>
        </Stack>
        <Typography variant="caption" color="text.secondary">
          {ORDER_TYPE_HINT[order.type]}
        </Typography>
      </TableCell>

      <TableCell sx={{ minWidth: 170 }}>
        <Box component="ul" sx={{ m: 0, p: 0, listStyle: 'none' }}>
          {order.items.map((item) => (
            <li key={item.menu_item_id}>
              <Box component="span" sx={{ fontWeight: 700, ...numeric }}>
                {item.quantity}×
              </Box>{' '}
              {item.name}
            </li>
          ))}
        </Box>
      </TableCell>

      <TableCell align="right" sx={numeric}>
        <Typography sx={{ ...numeric, fontWeight: 600 }}>{formatDuration(order.wait_minutes)}</Typography>
        <Typography variant="caption" color="text.secondary">
          since {formatTime(order.placed_at)}
        </Typography>
      </TableCell>

      <TableCell sx={numeric}>
        <PromisedTime order={order} />
      </TableCell>

      <TableCell>
        <StatusProgress status={order.status} />
      </TableCell>

      <TableCell align="right" sx={pinnedRight}>
        <OrderActions order={order} disabled={pending} onAction={onAction} />
      </TableCell>
    </TableRow>
  )
}

/** "15:26" over "in 20 min", or "5 min late" in the error color. Minutes come from the API. */
function PromisedTime({ order }: { order: QueueOrder }) {
  if (order.promised_at === null || order.minutes_until_promised === null) {
    return (
      <Typography variant="body2" color="text.secondary">
        No promise
      </Typography>
    )
  }
  const late = order.minutes_until_promised < 0
  return (
    <>
      <Typography sx={{ ...numeric, fontWeight: 600 }}>{formatTime(order.promised_at)}</Typography>
      <Typography variant="caption" color={late ? 'error' : 'text.secondary'} sx={{ fontWeight: late ? 700 : 400 }}>
        {formatMinutesUntil(order.minutes_until_promised)}
      </Typography>
    </>
  )
}

