import { AppBar, Box, Button, CircularProgress, Stack, Toolbar, Typography } from '@mui/material'
import RefreshRoundedIcon from '@mui/icons-material/RefreshRounded'
import RestaurantMenuRoundedIcon from '@mui/icons-material/RestaurantMenuRounded'
import { formatAgo, formatTime } from '../format'
import { useNow } from '../hooks/useNow'

interface AppHeaderProps {
  generatedAt: string | null // when the API computed the data on screen
  refreshing: boolean
  offline: boolean // the last refresh failed
  autoRefreshSeconds: number
  onRefresh: () => void
}

/** Title, a one-line explanation of the screen, a live clock and how fresh the data is. */
export function AppHeader({ generatedAt, refreshing, offline, autoRefreshSeconds, onRefresh }: AppHeaderProps) {
  const now = useNow(1000)

  return (
    <AppBar position="static" color="inherit" elevation={0} sx={{ borderBottom: 1, borderColor: 'divider' }}>
      <Toolbar sx={{ gap: 2, minHeight: { xs: 64 } }}>
        <Box
          sx={{
            width: 36,
            height: 36,
            borderRadius: 2,
            bgcolor: 'primary.main',
            color: 'primary.contrastText',
            display: 'grid',
            placeItems: 'center',
            flexShrink: 0,
          }}
          aria-hidden
        >
          <RestaurantMenuRoundedIcon fontSize="small" />
        </Box>
        <Box sx={{ flexGrow: 1, minWidth: 0 }}>
          <Typography variant="h6" component="h1" sx={{ lineHeight: 1.2, fontWeight: 700 }}>
            Kitchen Display
          </Typography>
          <Typography variant="caption" color="text.secondary">
            Orders ranked by priority. Work from the top: start preparing, then mark as ready. Ready orders move
            to “Ready for pickup”.
          </Typography>
        </Box>

        <Stack alignItems="flex-end" sx={{ flexShrink: 0 }}>
          <Typography sx={{ fontVariantNumeric: 'tabular-nums', fontWeight: 700, fontSize: 18, lineHeight: 1.2 }}>
            {formatTime(now.toISOString(), true)}
          </Typography>
          <FreshnessIndicator
            generatedAt={generatedAt}
            now={now}
            offline={offline}
            autoRefreshSeconds={autoRefreshSeconds}
          />
        </Stack>

        <Button
          variant="outlined"
          size="small"
          onClick={onRefresh}
          disabled={refreshing}
          startIcon={refreshing ? <CircularProgress size={14} color="inherit" /> : <RefreshRoundedIcon />}
          sx={{ flexShrink: 0, minWidth: 116 }}
        >
          {refreshing ? 'Refreshing…' : 'Refresh'}
        </Button>
      </Toolbar>
    </AppBar>
  )
}

/** "● Live · updated 4 s ago" (green), or "● Offline · retrying" (red) when the last refresh failed. */
function FreshnessIndicator({
  generatedAt,
  now,
  offline,
  autoRefreshSeconds,
}: {
  generatedAt: string | null
  now: Date
  offline: boolean
  autoRefreshSeconds: number
}) {
  const color = offline ? 'error.main' : 'success.main'
  const text = offline
    ? `Offline · retrying every ${autoRefreshSeconds} s`
    : generatedAt
      ? `Live · updated ${formatAgo(new Date(generatedAt), now)}`
      : 'Connecting…'

  return (
    <Stack direction="row" alignItems="center" spacing={0.75} aria-live="polite">
      <Box
        sx={{
          width: 8,
          height: 8,
          borderRadius: '50%',
          bgcolor: color,
          // A slow pulse says "this updates by itself"; respects reduced-motion preferences.
          '@media (prefers-reduced-motion: no-preference)': {
            animation: offline ? 'none' : 'pulse 2s ease-in-out infinite',
          },
          '@keyframes pulse': { '0%, 100%': { opacity: 1 }, '50%': { opacity: 0.35 } },
        }}
      />
      <Typography variant="caption" color="text.secondary" sx={{ whiteSpace: 'nowrap' }}>
        {text}
      </Typography>
    </Stack>
  )
}

