import type { ReactNode } from 'react'
import { Box, ButtonBase, Paper, Typography } from '@mui/material'
import type { Order } from '../api/orders'
import { formatDuration } from '../format'

export type SummaryTarget = 'received' | 'preparing' | 'ready'

interface SummaryCardsProps {
  activeOrders: Order[] | null // the API's default queue (received + preparing)
  readyOrders: Order[] | null
  onSelect: (target: SummaryTarget) => void
}

/**
 * The state of the kitchen in five numbers. Counts and maximums of values the API sent;
 * nothing here ranks or scores orders.
 */
export function SummaryCards({ activeOrders, readyOrders, onSelect }: SummaryCardsProps) {
  const active = activeOrders ?? []
  const ready = readyOrders ?? []
  const late = [...active, ...ready].filter((o) => o.minutes_until_promised !== null && o.minutes_until_promised < 0)
  const longest = active.reduce<Order | null>((max, o) => (max === null || o.wait_minutes > max.wait_minutes ? o : max), null)
  const loaded = activeOrders !== null

  return (
    <Box
      sx={{
        display: 'grid',
        gap: 1.5,
        gridTemplateColumns: { xs: 'repeat(2, 1fr)', md: 'repeat(5, 1fr)' },
        px: 2,
        pt: 2,
      }}
    >
      <SummaryCard
        label="Waiting to start"
        value={loaded ? active.filter((o) => o.status === 'received').length : '–'}
        caption="received, not started"
        accent="info.main"
        onClick={() => onSelect('received')}
      />
      <SummaryCard
        label="In preparation"
        value={loaded ? active.filter((o) => o.status === 'preparing').length : '–'}
        caption="being cooked now"
        accent="warning.main"
        onClick={() => onSelect('preparing')}
      />
      <SummaryCard
        label="Ready for pickup"
        value={readyOrders ? ready.length : '–'}
        caption="waiting for customer or courier"
        accent="success.main"
        onClick={() => onSelect('ready')}
      />
      <SummaryCard
        label="Late promises"
        value={loaded ? late.length : '–'}
        caption={late.length > 0 ? `orders ${late.map((o) => `#${o.id}`).join(', ')}` : 'all promises on time'}
        accent={late.length > 0 ? 'error.main' : 'divider'}
        highlight={late.length > 0}
      />
      <SummaryCard
        label="Longest wait"
        value={longest ? formatDuration(longest.wait_minutes) : '–'}
        caption={longest ? `order #${longest.id} · ${longest.customer_name}` : 'no active orders'}
        accent="divider"
      />
    </Box>
  )
}

interface SummaryCardProps {
  label: string
  value: ReactNode
  caption: string
  accent: string // theme color for the top border
  highlight?: boolean
  onClick?: () => void
}

function SummaryCard({ label, value, caption, accent, highlight = false, onClick }: SummaryCardProps) {
  const content = (
    <Box sx={{ p: 1.5, width: '100%', textAlign: 'left' }}>
      <Typography variant="caption" color="text.secondary" sx={{ fontWeight: 600, textTransform: 'uppercase', letterSpacing: 0.4 }}>
        {label}
      </Typography>
      <Typography
        sx={{ fontSize: 26, fontWeight: 700, lineHeight: 1.25, fontVariantNumeric: 'tabular-nums', color: highlight ? 'error.main' : 'text.primary' }}
      >
        {value}
      </Typography>
      <Typography variant="caption" color="text.secondary" noWrap component="div">
        {caption}
      </Typography>
    </Box>
  )

  return (
    <Paper variant="outlined" sx={{ borderTop: 3, borderTopColor: accent, overflow: 'hidden' }}>
      {onClick ? (
        <ButtonBase onClick={onClick} sx={{ width: '100%', '&:hover': { bgcolor: 'action.hover' } }} aria-label={`${label}: show orders`}>
          {content}
        </ButtonBase>
      ) : (
        content
      )}
    </Paper>
  )
}

