import { createTheme } from '@mui/material'

// Visual identity aligned with the client's site (rxredefined.com, also built on MUI):
// Nunito Sans, deep navy surfaces, cyan accent, bold weights, 8px corners.
//
// Accessibility (WCAG AA, 4.5:1 for text), measured:
// - the client's cyan #02AACE with white text is 2.75:1, so it is only used on the navy header
//   (6.51:1); buttons and text on white use the deeper shade #007C99 (4.84:1 with white);
// - MUI's default info/warning/success fail with white text, so status colors are darker shades.
export const BRAND = {
  navy: '#061925',
  cyan: '#02AACE', // on navy only
  cyanDeep: '#007C99', // on white
} as const

export const theme = createTheme({
  palette: {
    primary: { main: BRAND.cyanDeep, dark: '#006379', contrastText: '#ffffff' },
    secondary: { main: BRAND.navy, contrastText: '#ffffff' },
    info: { main: BRAND.cyanDeep },
    warning: { main: '#a84300' },
    success: { main: '#1b5e20' },
    text: { primary: BRAND.navy, secondary: '#3d4c55' },
    background: { default: '#f2f3f4', paper: '#ffffff' },
    divider: '#e1e4e6',
  },
  typography: {
    fontFamily: '"Nunito Sans Variable", "Nunito Sans", system-ui, -apple-system, "Segoe UI", Roboto, sans-serif',
    fontSize: 13,
    h6: { fontWeight: 800 },
    button: { textTransform: 'none', fontWeight: 700 },
  },
  shape: { borderRadius: 8 },
  components: {
    MuiButton: { defaultProps: { disableElevation: true } },
    MuiPaper: { styleOverrides: { outlined: { borderColor: '#e1e4e6' } } },
    MuiTab: { styleOverrides: { root: { textTransform: 'none', fontWeight: 700, minHeight: 48 } } },
    MuiToggleButton: {
      styleOverrides: { root: { textTransform: 'none', fontWeight: 700, paddingTop: 4, paddingBottom: 4 } },
    },
    MuiChip: { styleOverrides: { root: { fontWeight: 700 } } },
    MuiTableCell: {
      styleOverrides: {
        root: { borderColor: '#eceef0' },
        head: {
          fontWeight: 800,
          fontSize: 11.5,
          color: '#3d4c55',
          backgroundColor: '#f7f8f9',
          textTransform: 'uppercase',
          letterSpacing: 0.4,
          whiteSpace: 'nowrap',
        },
      },
    },
  },
})

