import type { ReactNode } from 'react'
import {
  LinearProgress,
  Stack,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Tooltip,
  Typography,
} from '@mui/material'
import InfoOutlinedIcon from '@mui/icons-material/InfoOutlined'
import { pinnedRight } from './tableStyles'

export interface Column {
  label: string
  width?: number // px; fixed widths keep the three tables lined up the same way
  help?: string // explanation shown in a tooltip on the header's info icon
}

interface OrdersTableShellProps {
  label: string // accessible name of the table
  columns: Column[]
  pinLastColumn?: boolean
  loading: boolean
  isEmpty: boolean
  emptyMessage: string
  children: ReactNode // the body rows
}

/**
 * The frame every order table shares: header, loading bar, empty state. Every column is
 * left-aligned, header and content alike, so labels always sit above what they describe.
 */
export function OrdersTableShell({
  label,
  columns,
  pinLastColumn = false,
  loading,
  isEmpty,
  emptyMessage,
  children,
}: OrdersTableShellProps) {
  return (
    <TableContainer sx={{ flex: 1, minHeight: 0 }}>
      {/* Keeps its height while hidden so the table does not jump on every refresh. */}
      <LinearProgress sx={{ visibility: loading ? 'visible' : 'hidden', height: 2 }} aria-hidden={!loading} />
      <Table size="small" stickyHeader aria-label={label}>
        <TableHead>
          <TableRow>
            {columns.map((column, index) => (
              <TableCell
                key={column.label}
                sx={{
                  width: column.width,
                  // Above the sticky body cells; keeps the header's own background.
                  ...(pinLastColumn && index === columns.length - 1 && { ...pinnedRight, bgcolor: undefined, zIndex: 3 }),
                }}
              >
                {column.help ? (
                  <Stack direction="row" alignItems="center" spacing={0.5}>
                    <span>{column.label}</span>
                    <Tooltip title={column.help}>
                      <InfoOutlinedIcon sx={{ fontSize: 14, color: 'text.secondary', cursor: 'help' }} aria-label={column.help} />
                    </Tooltip>
                  </Stack>
                ) : (
                  column.label
                )}
              </TableCell>
            ))}
          </TableRow>
        </TableHead>
        <TableBody>
          {isEmpty && (
            <TableRow>
              <TableCell colSpan={columns.length} align="center" sx={{ py: 8 }}>
                <Typography color="text.secondary">{emptyMessage}</Typography>
              </TableCell>
            </TableRow>
          )}
          {children}
        </TableBody>
      </Table>
    </TableContainer>
  )
}

