// Style fragments and column widths shared by the order tables (kept apart from components so
// Vite's fast refresh keeps working).

/** Fixed-width digits, no wrapping: numbers line up for comparison. */
export const numeric = { fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' } as const

/** The same column is the same width in every table. Items takes whatever space is left. */
export const COLUMN_WIDTH = {
  priority: 92,
  order: 150,
  vip: 76,
  type: 170,
  time: 120, // Waiting, Ready for, Finished
  promised: 120,
  status: 260,
  outcome: 140,
  actions: 250,
} as const

// On narrow screens (a kitchen tablet) the table scrolls sideways; the last column (actions)
// stays pinned to the right edge so the expeditor never loses the buttons. The soft shadow
// shows that other columns scroll underneath it.
export const pinnedRight = {
  position: 'sticky',
  right: 0,
  bgcolor: 'background.paper',
  boxShadow: '-8px 0 8px -8px rgba(0, 0, 0, 0.2)',
} as const

/** A solid hover color on every cell, so the pinned cell highlights with its row. */
export const rowSx = { '&:hover > td': { bgcolor: '#f7fbfc' } } as const

