     1	// Turns every error into the API's single error shape: { error: { code, message, details? } }.
     2	const { AppError } = require('../errors');
     3	
     4	function sendError(res, error) {
     5	  res.status(error.httpStatus).json({
     6	    error: { code: error.code, message: error.message, details: error.details },
     7	  });
     8	}
