    10	function notFoundHandler(req, res) {
    11	  sendError(res, new AppError('ROUTE_NOT_FOUND', `No route for ${req.method} ${req.path}.`));
    12	}
    13	
    14	// Express recognizes error middleware by its four parameters.
    15	function errorHandler(error, req, res, next) {
    16	  // A response already in flight cannot be replaced; let Express close the connection.
    17	  if (res.headersSent) return next(error);
    18	
    19	  if (error instanceof AppError) return sendError(res, error);
    20	
    21	  // Errors Express raises itself for a bad request (e.g. malformed URL encoding) carry a 4xx status.
    22	  if (error.status >= 400 && error.status < 500) {
    23	    return sendError(res, new AppError('BAD_REQUEST', 'The request is malformed.'));
    24	  }
    25	
    26	  // Unexpected: log the real cause for us, return nothing internal to the client.
    27	  console.error(error);
    28	  return sendError(res, new AppError('INTERNAL_ERROR', 'Unexpected server error.'));
