    32	    res.json({ generated_at: now.toISOString(), orders });
    33	  });
    34	
    35	  router.get('/finished', async (req, res) => {
    36	    const now = clock();
    37	    const orders = await ordersModule.getFinishedOrders({ now });
    38	    res.json({ generated_at: now.toISOString(), orders });
    39	  });
    40	
    41	  const transition = (action) => async (req, res) => {
    42	    const order = await ordersModule.transitionOrder({
    43	      id: parseOrderId(req.params.id),
    44	      action,
    45	      now: clock(),
    46	    });
    47	    res.json({ order });
    48	  };
    49	
    50	  router.post('/:id/start', transition('start'));
    51	  router.post('/:id/ready', transition('ready'));
    52	  router.post('/:id/pickup', transition('pickup'));
