     1	// Use cases for the expeditor screen. Applies the pure rules (queue, transitions) to data
     2	// loaded through the repository. Knows nothing about HTTP.
     3	const { AppError } = require('../errors');
     4	const repository = require('../repositories/orders.repository');
     5	const { resolveQueueStatuses, rankQueue, withComputedFields } = require('./queue');
     6	const { resolveTransition } = require('./transitions');
     7	
     8	// Views next to the active queue (which is ranked by score, see queue.js):
     9	// - ready: waiting for pickup, the one waiting longest first;
    10	// - finished: the most recent first, capped, because the screen shows recent history, not an archive.
    11	const READY_STATUSES = ['ready'];
    12	const FINISHED_STATUSES = ['picked_up', 'cancelled'];
    13	const FINISHED_LIMIT = 20;
    14	
    15	async function getQueue({ status, now }) {
    16	  const statuses = resolveQueueStatuses(status);
    17	  const orders = await repository.findOrdersByStatuses(statuses);
    18	  return rankQueue(orders, now);
    19	}
    20	
    21	async function getReadyOrders({ now }) {
    22	  const orders = await repository.findOrdersByStatuses(READY_STATUSES, { byStatusChange: 'ASC' });
    23	  return orders.map((order) => withComputedFields(order, now));
    24	}
    25	
    26	async function getFinishedOrders({ now }) {
    27	  const orders = await repository.findOrdersByStatuses(FINISHED_STATUSES, {
    28	    byStatusChange: 'DESC',
    29	    limit: FINISHED_LIMIT,
    30	  });
    31	  return orders.map((order) => withComputedFields(order, now));
    32	}
    33	
    34	const orderNotFound = (id) => new AppError('ORDER_NOT_FOUND', `Order ${id} does not exist.`, { id });
    35	
    36	async function transitionOrder({ id, action, now }) {
    37	  const order = await repository.findOrderById(id);
    38	  if (!order) throw orderNotFound(id);
    39	
    40	  const nextStatus = resolveTransition(order.status, action); // throws INVALID_TRANSITION
    41	
    42	  const moved = await repository.updateStatusIfCurrent(id, order.status, nextStatus, now);
    43	  if (!moved) {
    44	    // The status changed between our read and our write: another request won the race.
    45	    const current = await repository.findOrderById(id);
    46	    if (!current) throw orderNotFound(id);
    47	    throw new AppError(
    48	      'INVALID_TRANSITION',
    49	      `Order ${id} was changed to ${current.status} by another request.`,
    50	      { action, current_status: current.status },
    51	    );
    52	  }
    53	
    54	  return withComputedFields({ ...order, status: nextStatus, status_changed_at: now }, now);
    55	}
    56	
    57	module.exports = { FINISHED_LIMIT, getQueue, getReadyOrders, getFinishedOrders, transitionOrder };
