     1	// Priority score for the kitchen queue (spec §5.1).
     2	// Pure: everything it needs arrives as arguments, including `now`. No clock, no database.
     3	
     4	const MS_PER_MINUTE = 60 * 1000;
     5	
     6	// Every tunable number of the ranking lives here, so a product change to the
     7	// ranking is a one-place edit (plus its test).
     8	const PRIORITY_RULES = {
     9	  typePoints: { dine_in: 30, takeout: 20, delivery: 10 },
    10	  vipPoints: 20,
    11	  wait: { stepMinutes: 10, pointsPerStep: 5, max: 40 },
    12	  // Checked in order: the first bucket that covers the minutes left wins.
    13	  // A promise further away than every bucket, or no promise at all, scores 0.
    14	  promised: [
    15	    { upToMinutes: 30, points: 25 },
    16	    { upToMinutes: 60, points: 15 },
    17	  ],
    18	  complexity: { stepMinutes: 15, pointsPerStep: 5, max: 20 },
    19	};
    20	
    21	// Whole minutes from `from` to `to`, floored (9m50s -> 9). Negative when `to` is earlier.
    22	function wholeMinutesBetween(from, to) {
