cd /c/Users/MariaLauraPrataVieir/kitchen_service_ML/api/src/schema/seeders && node - <<'EOF'
const fs = require('fs');
const f = '20261006000001-demo-data.js';
let s = fs.readFileSync(f, 'utf8');
const start = s.indexOf('// What the seed must demonstrate');
const end = s.indexOf('/** @type');
if (start < 0 || end < 0) throw new Error('markers not found');
const block = `// A believable lunch rush, so the screen makes sense to the person using it: orders started
// earlier are already cooking, recent ones wait to start, far-off pre-orders wait on purpose.
// Scores are the values right after seeding; the active queue then reads:
//   Alice 80 (received, Next up) · Ben 65 (preparing) · Felix 60 · Emma 60 · Grace 55 (preparing)
//   · Chloe 25 · David 25
//
// What the seed must demonstrate (spec §9.5) and which rows do it:
//   every order type ............ dine_in, takeout and delivery all appear below
//   VIP and non-VIP ............. Felix Carter / Iris Bennett are VIP, the rest are not
//   wait-time cap ............... Alice Morgan (a pre-order placed 90 min ago)
//   complexity cap .............. Ben Turner
//   tie broken by promised_at ... Felix Carter vs Emma Brooks, Chloe Davis vs David Reed
//   received, preparing, ready .. statuses below; Henry Ward and Kate Moore are \`ready\`
//                                 (not in the active queue)
// Names are fictional (spec §3: no real customer data).
//
// \`placed\` = minutes ago, \`promised\` = minutes from now (negative = in the past), null = no promise,
// \`changed\` = minutes since the last status change (defaults to \`placed\`: never moved).
const ORDERS = [
  // Wait-time cap. A takeout pre-order: placed 90 min ago for a pickup 45 min from now, so the
  // kitchen rightly has not started it; now that pickup is near it climbs to the top.
  // 20 + 40 (cap) + 15 + 5 = 80
  { customer_name: 'Alice Morgan', type: 'takeout', is_vip: false, status: 'received', placed: 90, promised: 45,
    items: [['Mushroom Risotto', 1]] },

  // Complexity cap: 2x25 + 20 = 70 prep minutes -> 20 (the max). Placed 35 min ago, cooking for 15.
  // 30 + 15 + 0 + 20 = 65
  { customer_name: 'Ben Turner', type: 'dine_in', is_vip: false, status: 'preparing', placed: 35, changed: 15, promised: null,
    items: [['Ribeye Steak', 2], ['Grilled Salmon', 1]] },

  // Like spec Example B: delivery VIP, promise in 20 min. 10 + 20 + 5 + 25 + 0 = 60
  { customer_name: 'Felix Carter', type: 'delivery', is_vip: true, status: 'received', placed: 10, promised: 20,
    items: [['Margherita Pizza', 1]] },
  // Like spec Example A: dine_in, no promise. 30 + 15 + 0 + 15 = 60 -> ties with Felix, who ranks
  // first because he has a promised_at. Placed 30 min ago (not 35 as in the spec) so both orders
  // are exactly 20 min apart, gain wait points at the same moment, and the tie holds for ~50 min.
  { customer_name: 'Emma Brooks', type: 'dine_in', is_vip: false, status: 'received', placed: 30, promised: null,
    items: [['Grilled Salmon', 2], ['Caesar Salad', 1], ['Espresso', 1]] },

  // 31-60 min promise bucket. Placed 32 min ago, cooking for 12. 20 + 15 + 15 + 5 = 55
  { customer_name: 'Grace Hill', type: 'takeout', is_vip: false, status: 'preparing', placed: 32, changed: 12, promised: 45,
    items: [['Caesar Salad', 1], ['Tiramisu', 1]] },

  // Score tie broken by promised_at: two identical pre-orders for this evening, placed at the same
  // instant, both promises more than 60 min away (0 points). 20 + 5 = 25 each; Chloe (earlier
  // promise) ranks above David. Stable for ~2 hours, until Chloe's promise enters the 60-minute bucket.
  { customer_name: 'Chloe Davis', type: 'takeout', is_vip: false, status: 'received', placed: 15, promised: 180,
    items: [['Margherita Pizza', 1], ['Lemonade', 1]] },
  { customer_name: 'David Reed', type: 'takeout', is_vip: false, status: 'received', placed: 15, promised: 240,
    items: [['Margherita Pizza', 1], ['Lemonade', 1]] },

  // Not in the active queue. Ready for pickup (the courier for Kate's delivery is already late):
  { customer_name: 'Henry Ward', type: 'takeout', is_vip: false, status: 'ready', placed: 40, changed: 4, promised: 5,
    items: [['Bruschetta', 2]] },
  { customer_name: 'Kate Moore', type: 'delivery', is_vip: false, status: 'ready', placed: 45, changed: 9, promised: -2,
    items: [['Mushroom Risotto', 1], ['Lemonade', 2]] },
  // Finished.
  { customer_name: 'Iris Bennett', type: 'delivery', is_vip: true, status: 'picked_up', placed: 120, changed: 55, promised: -60,
    items: [['Chocolate Lava Cake', 1]] },
  { customer_name: 'Liam Price', type: 'dine_in', is_vip: false, status: 'picked_up', placed: 70, changed: 10, promised: null,
    items: [['Grilled Salmon', 1], ['Espresso', 2]] },
  { customer_name: 'Jack Foster', type: 'dine_in', is_vip: false, status: 'cancelled', placed: 25, changed: 18, promised: null,
    items: [['Ribeye Steak', 1]] },
];

`;
s = s.slice(0, start) + block + s.slice(end);
s = s.replace(`// so the demo never goes stale: re-run \`npm run db:setup\` to refresh it.
// Scores in the comments are the values right after seeding.`, `// so the demo never goes stale: re-run \`npm run db:setup\` to refresh it.`);
fs.writeFileSync(f, s);
console.log('ok');
EOF

