file.content:
  orders: Order[] | null // null = nothing loaded for this filter yet
  filter: QueueFilter
  loading: boolean
  pendingOrderId: number | null
  onAction: (order: Order, action: OrderAction) => void
}

/**
 * The spec's kitchen queue. Renders the orders exactly in the order the API returned them:
 * position 1 is simply the first row. No sorting, no scoring here.
 */
export function QueueTable({ orders, filter, loading, pendingOrderId, onAction }: QueueTableProps) {
  return (
    <OrdersTableShell
      label="Kitchen queue"
      columns={COLUMNS}
      pinLastColumn
      loading={loading}
      isEmpty={orders?.length === 0}
      emptyMessage={EMPTY_QUEUE_MESSAGE[filter]}
    >
      {orders?.map((order, index) => {
        const isNext = index === 0
        return (
          <TableRow
            key={order.id}
            sx={{
              ...rowSx,
              // The first row is what the kitchen should work on next: marked with an accent bar.
              ...(isNext && { '& > td:first-of-type': { boxShadow: (t) => `inset 4px 0 0 ${t.palette.primary.main}` } }),
            }}
          >
            <TableCell sx={{ whiteSpace: 'nowrap' }}>
              <Stack direction="row" alignItems="baseline" spacing={1}>
                <Typography component="span" sx={{ ...numeric, fontWeight: 700, fontSize: 18, minWidth: 20 }}>
                  {index + 1}
                </Typography>
                <Typography component="span" variant="caption" color="text.secondary" sx={numeric}>
                  score {order.score}
                </Typography>
              </Stack>
              {isNext && <Chip label="Next up" color="primary" size="small" sx={{ mt: 0.5 }} />}
            </TableCell>
            <TableCell>
              <OrderCell order={order} />
            </TableCell>
            <TableCell>
              <VipCell isVip={order.is_vip} />
            </TableCell>
            <TableCell>
              <TypeCell type={order.type} />
            </TableCell>
            <TableCell sx={{ minWidth: 170 }}>
              <ItemsCell order={order} />
            </TableCell>
            <TableCell>
              <DurationCell minutes={order.wait_minutes} caption={`since ${formatTime(order.placed_at)}`} />
            </TableCell>
            <TableCell>
              <PromisedCell order={order} />
            </TableCell>
            <TableCell>
              <StatusProgress status={order.status} />
            </TableCell>
            <TableCell sx={pinnedRight}>
              <OrderActions order={order} disabled={pendingOrderId === order.id} onAction={onAction} />
            </TableCell>
          </TableRow>
        )
      })}

