/**
 * @param {object} order  { type, is_vip, placed_at, promised_at, items: [{ prep_time_minutes, quantity }] }
 * @param {Date} now      the moment the queue is computed (real clock in the app, frozen in tests)
 * @param {object} [rules] scoring weights; defaults to PRIORITY_RULES
 * @returns {number}
 */
function computeScore(order, now, rules = PRIORITY_RULES) {
  return (
    typePoints(order.type, rules.typePoints) +
    (order.is_vip ? rules.vipPoints : 0) +
    steppedPoints(minutesWaiting(order.placed_at, now), rules.wait) +
    promisedPoints(order.promised_at, now, rules.promised) +
    steppedPoints(totalPrepMinutes(order.items), rules.complexity)
  );
}

module.exports = { PRIORITY_RULES, computeScore, minutesWaiting, minutesUntilPromised };

input.new_string:
const steppedFormula = (value, { stepMinutes, pointsPerStep, max }) =>
  `min(${max}, floor(${value} / ${stepMinutes}) × ${pointsPerStep})`;

function describePromise(minutesLeft) {
  if (minutesLeft === null) return 'No promised time';
  if (minutesLeft < 0) return `Promised ${-minutesLeft} min ago (late)`;
  return `Promised in ${minutesLeft} min`;
}

/**
 * The score, part by part, in plain words, with the arithmetic of each part. Built from the same
 * helpers and PRIORITY_RULES as the score itself, so the explanation can never disagree with it
 * and follows any change to the rules. Pure, like computeScore.
 * @returns {{ component: string, label: string, formula: string, points: number }[]}
 */
function scoreBreakdown(order, now, rules = PRIORITY_RULES) {
  const waited = minutesWaiting(order.placed_at, now);
  const minutesLeft = minutesUntilPromised(order.promised_at, now);
  const prep = totalPrepMinutes(order.items);

  return [
    {
      component: 'type',
      label: `${order.type.replace('_', '-')} order`,
      formula: Object.entries(rules.typePoints)
        .map(([type, points]) => `${type.replace('_', '-')} ${points}`)
        .join(' · '),
      points: typePoints(order.type, rules.typePoints),
    },
    {
      component: 'vip',
      label: order.is_vip ? 'VIP customer' : 'Not a VIP customer',
      formula: `VIP +${rules.vipPoints}`,
      points: order.is_vip ? rules.vipPoints : 0,
    },
    {
      component: 'wait',
      label: `Waiting ${waited} min since it was placed`,
      formula: steppedFormula(waited, rules.wait),
      points: steppedPoints(waited, rules.wait),
    },
    {
      component: 'promise',
      label: describePromise(minutesLeft),
      formula: [
        ...rules.promised.map((bucket) => `≤ ${bucket.upToMinutes} min: ${bucket.points}`),
        'later or none: 0',
      ].join(' · '),
      points: promisedPoints(order.promised_at, now, rules.promised),
    },
    {
      component: 'complexity',
      label: `${prep} min of total prep time`,
      formula: steppedFormula(prep, rules.complexity),
      points: steppedPoints(prep, rules.complexity),
    },
  ];
}

/**
 * The priority score (spec §5.1): the sum of the parts above.
 * @param {object} order  { type, is_vip, placed_at, promised_at, items: [{ prep_time_minutes, quantity }] }
 * @param {Date} now      the moment the queue is computed (real clock in the app, frozen in tests)
 * @param {object} [rules] scoring weights; defaults to PRIORITY_RULES
