describe('scoreBreakdown — the score explained, part by part', () => {
  const { scoreBreakdown, PRIORITY_RULES } = require('../../src/modules/priority');

  const exampleA = buildOrder({
    type: 'dine_in',
    placed_at: new Date('2026-06-15T11:25:00Z'),
    items: [item(MENU.grilledSalmon, 2), item(MENU.caesarSalad, 1)],
  });

  test('spec Example A: each part, in words, with its arithmetic', () => {
    expect(scoreBreakdown(exampleA, NOW)).toEqual([
      { component: 'type', label: 'dine-in order', formula: 'dine-in 30 · takeout 20 · delivery 10', points: 30 },
      { component: 'vip', label: 'Not a VIP customer', formula: 'VIP +20', points: 0 },
      { component: 'wait', label: 'Waiting 35 min since it was placed', formula: 'min(40, floor(35 / 10) × 5)', points: 15 },
      { component: 'promise', label: 'No promised time', formula: '≤ 30 min: 25 · ≤ 60 min: 15 · later or none: 0', points: 0 },
      { component: 'complexity', label: '50 min of total prep time', formula: 'min(20, floor(50 / 15) × 5)', points: 15 },
    ]);
  });

  test.each([
    ['spec Example A', exampleA],
    ['a late VIP delivery', buildOrder({ is_vip: true, placed_at: minutesAgo(95), promised_at: minutesAgo(5), items: [item(MENU.grilledSalmon, 4)] })],
    ['an empty takeout order', buildOrder({ type: 'takeout' })],
  ])('the parts always add up to computeScore: %s', (_label, order) => {
    const total = scoreBreakdown(order, NOW).reduce((sum, part) => sum + part.points, 0);
    expect(total).toBe(computeScore(order, NOW));
  });

  test.each([
    [minutesFromNow(20), 'Promised in 20 min'],
    [minutesAgo(5), 'Promised 5 min ago (late)'],
    [null, 'No promised time'],
  ])('promise described in words: %p -> %s', (promisedAt, label) => {
    const promise = scoreBreakdown(buildOrder({ promised_at: promisedAt }), NOW).find((p) => p.component === 'promise');
    expect(promise.label).toBe(label);
  });

  test('follows the rules: a changed weight shows up in both the points and the explanation', () => {
    const rules = { ...PRIORITY_RULES, vipPoints: 30 };
    const vip = scoreBreakdown(buildOrder({ is_vip: true }), NOW, rules).find((p) => p.component === 'vip');
    expect(vip).toMatchObject({ formula: 'VIP +30', points: 30 });
  });
});
EOF
