describe('rank_reason — why each order sits above the next one', () => {
  const reasons = (orders) => rankQueue(orders, NOW).map((o) => o.rank_reason);

  test('higher score', () => {
    const [reason] = reasons([buildOrder({ id: 1, type: 'dine_in' }), buildOrder({ id: 2, customer_name: 'Bob' })]);
    expect(reason).toBe('Ahead of #2 Bob because its score is higher (30 vs 10).');
  });

  test('tie: a promised time beats no promised time (spec Example B over A)', () => {
    const [reason] = reasons([
      buildOrder({ id: 1, customer_name: 'Ann' }),
      buildOrder({ id: 2, promised_at: minutesFromNow(240) }),
    ]);
    expect(reason).toBe('Same score as #1 Ann (10). Ahead because it has a promised time and the other does not.');
  });

  test('tie: earlier promised time', () => {
    const [reason] = reasons([
      buildOrder({ id: 1, customer_name: 'Ann', promised_at: minutesFromNow(240) }),
      buildOrder({ id: 2, promised_at: minutesFromNow(120) }),
    ]);
    expect(reason).toMatch(/Ahead because its promised time is earlier\.$/);
  });

  test('tie: placed earlier', () => {
    const [reason] = reasons([buildOrder({ id: 1, placed_at: minutesAgo(1) }), buildOrder({ id: 2, placed_at: minutesAgo(4) })]);
    expect(reason).toMatch(/Ahead because it was placed earlier\.$/);
  });

  test('tie on everything: lower order number', () => {
    const [reason] = reasons([buildOrder({ id: 8 }), buildOrder({ id: 3 })]);
    expect(reason).toMatch(/Ahead because its order number is lower\.$/);
  });

  test('the last order has no one below it', () => {
    expect(reasons([buildOrder({ id: 1 }), buildOrder({ id: 2 })]).at(-1)).toBeNull();
  });
});
