// The queue order (spec §5.1 then §5.2), one criterion per line, each with the reason a person
// reads when it is the one that decided. The sort and the explanation both use this list, so a
// new or reordered tie-break is a one-place change and its explanation follows.
const QUEUE_ORDER = [
  {
    compare: (a, b) => b.score - a.score,
    reason: (a, b) => `its score is higher (${a.score} vs ${b.score})`,
  },
  {
    compare: (a, b) => compareTimesNullLast(a.promised_at, b.promised_at),
    reason: (a, b) =>
      b.promised_at == null ? 'it has a promised time and the other does not' : 'its promised time is earlier',
  },
  {
    compare: (a, b) => compareTimesNullLast(a.placed_at, b.placed_at),
    reason: () => 'it was placed earlier',
  },
  {
    compare: (a, b) => a.id - b.id,
    reason: () => 'its order number is lower',
  },
];

// Highest score first, then the tie-breaks: the first criterion that is not a tie decides.
function compareQueue(a, b) {
  for (const criterion of QUEUE_ORDER) {
    const result = criterion.compare(a, b);
    if (result !== 0) return result;
  }
  return 0;
}

// Why `a` sits directly above `b`, in words, e.g.
// "Same score as #4 Emma Brooks (60). Ahead because it has a promised time and the other does not."
function rankReason(a, b) {
  const decisive = QUEUE_ORDER.find((criterion) => criterion.compare(a, b) !== 0);
  const other = `#${b.id} ${b.customer_name}`;
  if (decisive === QUEUE_ORDER[0]) return `Ahead of ${other} because ${decisive.reason(a, b)}.`;
  return `Same score as ${other} (${a.score}). Ahead because ${decisive.reason(a, b)}.`;
}

// The order plus the values computed at request time. Never stored: they depend on `now`.
// The minute fields use the same `now` as the score, so the UI can display time without
// keeping a clock or any time rule of its own.
function withComputedFields(order, now) {
  return {
    ...order,
    score: computeScore(order, now),
    score_breakdown: scoreBreakdown(order, now),
    wait_minutes: minutesWaiting(order.placed_at, now),
    minutes_until_promised: minutesUntilPromised(order.promised_at, now),
    minutes_in_status: minutesWaiting(order.status_changed_at, now),
    allowed_actions: allowedActions(order.status),
  };
}

// Returns the orders in queue order, each with its computed fields and, except for the last one,
// the reason it sits above the next order.
function rankQueue(orders, now) {
  const ranked = orders.map((order) => withComputedFields(order, now)).sort(compareQueue);
  return ranked.map((order, index) => ({
    ...order,
    rank_reason: index < ranked.length - 1 ? rankReason(order, ranked[index + 1]) : null,
  }));
}

module.exports = { ACTIVE_STATUSES, resolveQueueStatuses, compareQueue, rankReason, withComputedFields, rankQueue };

