import type { ReactElement } from 'react'
import { Box, Divider, Stack, Tooltip, Typography } from '@mui/material'
import type { Order, RankCriterion, ScoreBreakdown } from '../api/orders'
import { formatDuration, ORDER_TYPE_LABEL } from '../format'
import { numeric } from './tableStyles'

interface ScoreExplanationProps {
  order: Order
  position: number
  next: Order | undefined // the order right below, named in the "ahead because" sentence
  children: ReactElement
}

/**
 * "Why is this order here?" in plain words — shown on hover, tap or keyboard focus of the
 * priority cell. The points of each part and the deciding rule come from the API
 * (score_breakdown, ahead_of_next); nothing is calculated here, the screen only puts them into words.
 */
export function ScoreExplanation({ order, position, next, children }: ScoreExplanationProps) {
  return (
    <Tooltip
      title={<ExplanationCard order={order} position={position} next={next} />}
      placement="right-start"
      enterTouchDelay={0} // a tap opens it on a kitchen tablet
      leaveTouchDelay={8000}
      slotProps={{
        tooltip: {
          sx: { bgcolor: 'background.paper', color: 'text.primary', boxShadow: 6, border: 1, borderColor: 'divider', p: 0, maxWidth: 360 },
        },
      }}
    >
      {children}
    </Tooltip>
  )
}

/** One line per part of the score, in the words a cook would use. */
function describeParts(order: Order): { key: keyof ScoreBreakdown; text: string }[] {
  const minutes = order.minutes_until_promised
  return [
    { key: 'type', text: `${ORDER_TYPE_LABEL[order.type]} order` },
    { key: 'vip', text: order.is_vip ? 'VIP customer' : 'Not a VIP customer' },
    { key: 'wait', text: `Waiting for ${formatDuration(order.wait_minutes)}` },
    {
      key: 'promise',
      text:
        minutes === null
          ? 'No promised time'
          : minutes < 0
            ? `Promised time passed ${formatDuration(-minutes)} ago`
            : `Promised in ${formatDuration(minutes)}`,
    },
    { key: 'complexity', text: 'Amount of preparation work' },
  ]
}

const AHEAD_BECAUSE: Record<Exclude<RankCriterion, 'score'>, (next: Order) => string> = {
  promised_at: (next) => (next.promised_at === null ? 'it has a promised time and that one does not' : 'its promised time is earlier'),
  placed_at: () => 'it was placed earlier',
  id: () => 'its order number is lower',
}

function aheadSentence(order: Order, next: Order | undefined): string {
  const ahead = order.ahead_of_next
  if (!ahead || !next) return 'Last in this view: nothing is ranked below it.'
  const other = `#${next.id} ${next.customer_name}`
  if (ahead.decided_by === 'score') return `Ahead of ${other} (score ${next.score}) because its score is higher.`
  return `Same score as ${other}. Ahead because ${AHEAD_BECAUSE[ahead.decided_by](next)}.`
}

function ExplanationCard({ order, position, next }: { order: Order; position: number; next: Order | undefined }) {
  return (
    <Box sx={{ p: 1.5, minWidth: 300 }}>
      <Typography sx={{ fontWeight: 800, fontSize: 14 }}>
        Why order #{order.id} is number {position}
      </Typography>
      <Typography variant="caption" color="text.secondary" component="div" sx={{ mb: 1 }}>
        Points it gets for each part of the priority score:
      </Typography>

      <Stack divider={<Divider flexItem />} spacing={0.75}>
        {describeParts(order).map((part) => (
          <Stack key={part.key} direction="row" justifyContent="space-between" spacing={2}>
            <Typography variant="body2">{part.text}</Typography>
            <Typography
              variant="body2"
              sx={{ ...numeric, fontWeight: 700, color: order.score_breakdown[part.key] > 0 ? 'primary.main' : 'text.secondary' }}
            >
              +{order.score_breakdown[part.key]}
            </Typography>
          </Stack>
        ))}
      </Stack>

      <Stack direction="row" justifyContent="space-between" sx={{ mt: 1, pt: 1, borderTop: 2, borderColor: 'text.primary' }}>
        <Typography sx={{ fontWeight: 800 }}>Priority score</Typography>
        <Typography sx={{ ...numeric, fontWeight: 800 }}>{order.score}</Typography>
      </Stack>

      <Typography variant="body2" sx={{ mt: 1.25, p: 1, borderRadius: 1, bgcolor: 'background.default' }}>
        {aheadSentence(order, next)}
      </Typography>
    </Box>
  )
}

