import type { Order } from '../api/orders'
import { numeric } from './tableStyles'

/**
 * "Why is this order here?" — shown on hover, tap or keyboard focus of the priority cell.
 * Every line comes from the API (score_breakdown, rank_reason): the screen does not hold a copy
 * of the scoring formula, it only lays the server's explanation out.
 */
export function ScoreExplanation({ order, position, children }: { order: Order; position: number; children: ReactElement }) {
  return (
    <Tooltip
      title={<ExplanationCard order={order} position={position} />}
      placement="right-start"
      enterTouchDelay={0} // a tap opens it on a kitchen tablet
      leaveTouchDelay={8000}
      slotProps={{
        tooltip: {
          sx: {
            bgcolor: 'background.paper',
            color: 'text.primary',
            boxShadow: 6,
            border: 1,
            borderColor: 'divider',
            p: 0,
            maxWidth: 380,
          },
        },
      }}
    >
      {children}
    </Tooltip>
  )
}

function ExplanationCard({ order, position }: { order: Order; position: number }) {
  return (
    <Box sx={{ p: 1.5, minWidth: 320 }}>
      <Typography sx={{ fontWeight: 800, fontSize: 14 }}>
        Why order #{order.id} is number {position}
      </Typography>
      <Typography variant="caption" color="text.secondary" component="div" sx={{ mb: 1 }}>
        Priority score, calculated by the server at the last update:
      </Typography>

      <Stack divider={<Divider flexItem />} spacing={0.75}>
        {order.score_breakdown.map((part) => (
          <Stack key={part.component} direction="row" justifyContent="space-between" spacing={2}>
            <Box>
              <Typography variant="body2" sx={{ fontWeight: 600, '&::first-letter': { textTransform: 'uppercase' } }}>
                {part.label}
              </Typography>
              <Typography variant="caption" color="text.secondary" sx={{ fontFamily: 'ui-monospace, monospace', fontSize: 11 }}>
                {part.formula}
              </Typography>
            </Box>
            <Typography sx={{ ...numeric, fontWeight: 700, color: part.points > 0 ? 'primary.main' : 'text.secondary' }}>
              +{part.points}
            </Typography>
          </Stack>
        ))}
      </Stack>

      <Stack direction="row" justifyContent="space-between" sx={{ mt: 1, pt: 1, borderTop: 2, borderColor: 'text.primary' }}>
        <Typography sx={{ fontWeight: 800 }}>Total score</Typography>
        <Typography sx={{ ...numeric, fontWeight: 800 }}>{order.score}</Typography>
      </Stack>

      <Typography variant="body2" sx={{ mt: 1.25, p: 1, borderRadius: 1, bgcolor: 'background.default' }}>
        {order.rank_reason ?? 'Last in this view: nothing is ranked below it.'}
      </Typography>
    </Box>
  )
}

