import { Box, ButtonBase, Chip, Stack, Typography } from '@mui/material'
import ChevronRightRoundedIcon from '@mui/icons-material/ChevronRightRounded'
import WarningAmberRoundedIcon from '@mui/icons-material/WarningAmberRounded'
import type { View } from '../format'
import { VIEW_HINT, VIEW_LABEL } from '../format'

interface StatusPipelineProps {
  value: View
  counts: Partial<Record<View, number>> // missing = not loaded yet
  lateOrderIds: number[]
  onChange: (view: View) => void
}

/**
 * The one control for choosing what the table shows, laid out as the path an order takes:
 * Received → Preparing → Ready → Finished. "All active", "Received" and "Preparing" are the
 * spec's queue filter (§8); "Ready" and "Finished" are the views after the kitchen.
 * Counts are lengths of lists the API returned.
 */
export function StatusPipeline({ value, counts, lateOrderIds, onChange }: StatusPipelineProps) {
  const step = (view: View) => (
    <PipelineStep key={view} view={view} selected={value === view} count={counts[view]} onSelect={onChange} />
  )
  const arrow = (key: string) => (
    <ChevronRightRoundedIcon key={key} sx={{ color: 'text.disabled', alignSelf: 'center', mt: 2.5 }} aria-hidden />
  )

  return (
    <Stack
      direction="row"
      alignItems="flex-start"
      justifyContent="space-between"
      flexWrap="wrap"
      useFlexGap
      sx={{ px: 2, pt: 2, gap: 2 }}
    >
