import { useState } from 'react'
import { Alert, AlertTitle, Box, Button, Paper, Snackbar, Stack, Tab, Tabs, Typography } from '@mui/material'
import { FINISHED_PATH, queuePath, READY_PATH, toApiError, transitionOrder } from './api/orders'
import type { ApiError, Order, OrderAction, QueueFilter as Filter } from './api/orders'
import { AppHeader } from './components/AppHeader'
import { ConfirmCancelDialog } from './components/ConfirmCancelDialog'
import { FinishedTable } from './components/FinishedTable'
import { QueueFilter } from './components/QueueFilter'
import { QueueTable } from './components/QueueTable'
import { ReadyTable } from './components/ReadyTable'
import { SummaryCards } from './components/SummaryCards'
import type { SummaryTarget } from './components/SummaryCards'
import { ACTION_LABEL, describeNewStatus } from './format'
import { useAutoRefresh } from './hooks/useAutoRefresh'
import { useOrders } from './hooks/useOrders'

const AUTO_REFRESH_SECONDS = 15

type View = 'queue' | 'ready' | 'finished'

interface ActionFailure {
  error: ApiError
  description: string // e.g. '"Start preparing" on order #4 (Ben Turner)'
}

/** The Kitchen Display: the ranked kitchen queue, plus the orders waiting for pickup and recently finished. */
export default function App() {
  const [view, setView] = useState<View>('queue')
  const [filter, setFilter] = useState<Filter>('active')
  const { tick, refresh } = useAutoRefresh(AUTO_REFRESH_SECONDS * 1000)

  // The active queue is always loaded: it feeds the summary cards and the default table.
  const active = useOrders(queuePath('active'), tick)
  const filtered = useOrders(filter === 'active' ? null : queuePath(filter), tick)
  const queue = filter === 'active' ? active : filtered
  const ready = useOrders(READY_PATH, tick)
  const finished = useOrders(view === 'finished' ? FINISHED_PATH : null, tick)
  const current = { queue, ready, finished }[view]

  const [pendingOrderId, setPendingOrderId] = useState<number | null>(null)
  const [actionFailure, setActionFailure] = useState<ActionFailure | null>(null)
  const [orderToCancel, setOrderToCancel] = useState<Order | null>(null)
  const [confirmOpen, setConfirmOpen] = useState(false)
  const [notice, setNotice] = useState<string | null>(null)

  async function runAction(order: Order, action: OrderAction) {
    setPendingOrderId(order.id)
    setActionFailure(null)
    try {
      const { order: updated } = await transitionOrder(order.id, action)
      setNotice(describeNewStatus(updated.id, updated.status))
    } catch (err) {
      setActionFailure({
        error: toApiError(err),
        description: `"${ACTION_LABEL[action]}" on order #${order.id} (${order.customer_name})`,
      })
    } finally {
      setPendingOrderId(null)
      // Reload either way: after a rejection the row then shows the order's real current status.
      refresh()
    }
  }

  function handleAction(order: Order, action: OrderAction) {
    if (action === 'cancel') {
      setOrderToCancel(order)
      setConfirmOpen(true)
    } else {
      void runAction(order, action)
    }
  }

  function showSummary(target: SummaryTarget) {
    if (target === 'ready') {
      setView('ready')
    } else {
      setView('queue')
      setFilter(target)
    }
  }

  return (
    <Box sx={{ height: '100vh', display: 'flex', flexDirection: 'column', bgcolor: 'background.default' }}>
      <AppHeader
        generatedAt={active.generatedAt}
        refreshing={active.loading || current.loading}
        offline={active.error !== null}
        autoRefreshSeconds={AUTO_REFRESH_SECONDS}
        onRefresh={refresh}
      />

      <Box component="main" sx={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column' }}>
        <SummaryCards activeOrders={active.orders} readyOrders={ready.orders} onSelect={showSummary} />

        <Paper
          variant="outlined"
          sx={{ m: 2, flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}
        >
          <Stack
            direction="row"
            alignItems="center"
            justifyContent="space-between"
            flexWrap="wrap"
            useFlexGap
            sx={{ px: 2, borderBottom: 1, borderColor: 'divider', columnGap: 2 }}
          >
            <Tabs value={view} onChange={(_event, next: View) => setView(next)} aria-label="Order views">
              <Tab value="queue" label={`Kitchen queue${countLabel(active.orders)}`} />
              <Tab value="ready" label={`Ready for pickup${countLabel(ready.orders)}`} />
              <Tab value="finished" label="Finished" />
            </Tabs>
            {view === 'queue' && (
              <Stack direction="row" alignItems="center" spacing={1.5} sx={{ py: 1 }}>
                <Typography variant="caption" color="text.secondary">
                  Show
                </Typography>
                <QueueFilter value={filter} onChange={setFilter} />
              </Stack>
            )}
          </Stack>

          {(actionFailure || current.error) && (
            <Stack spacing={1} sx={{ p: 2, pb: 0 }}>
              {actionFailure && (
                <Alert severity="error" onClose={() => setActionFailure(null)}>
                  <AlertTitle>{actionFailure.description} was rejected</AlertTitle>
                  {actionFailure.error.message} <code>{actionFailure.error.code}</code>
                </Alert>
              )}
              {current.error && (
                <Alert
                  severity="error"
                  action={
                    <Button color="inherit" size="small" onClick={refresh}>
                      Retry
                    </Button>
                  }
                >
                  <AlertTitle>Could not load this list</AlertTitle>
                  {current.error.message} <code>{current.error.code}</code>
                </Alert>
              )}
            </Stack>
          )}

          {view === 'queue' && (
            <QueueTable
              orders={queue.orders}
              filter={filter}
              loading={queue.loading}
              pendingOrderId={pendingOrderId}
              onAction={handleAction}
            />
          )}
          {view === 'ready' && (
            <ReadyTable orders={ready.orders} loading={ready.loading} pendingOrderId={pendingOrderId} onAction={handleAction} />
          )}
          {view === 'finished' && <FinishedTable orders={finished.orders} loading={finished.loading} />}
        </Paper>
      </Box>

      <ConfirmCancelDialog
        open={confirmOpen}
        order={orderToCancel}
        onClose={() => setConfirmOpen(false)}
        onConfirm={(order) => {
          setConfirmOpen(false)
          void runAction(order, 'cancel')
        }}
      />

      <Snackbar
        open={notice !== null}
        message={notice}
        autoHideDuration={5000}
        onClose={() => setNotice(null)}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'left' }}
      />
    </Box>
  )
}

/** " (7)" once the list has loaded. */
function countLabel(orders: Order[] | null): string {
  return orders ? ` (${orders.length})` : ''
}

