// Table cell contents shared by the queue, ready and finished tables, so an order reads the
// same way everywhere. One line per cell; secondary detail is in a tooltip (hover or tap).
// Presentation only: every value comes from the API.
import type { ReactNode } from 'react'
import { Box, Stack, Tooltip, Typography } from '@mui/material'
import DeliveryDiningOutlinedIcon from '@mui/icons-material/DeliveryDiningOutlined'
import RestaurantOutlinedIcon from '@mui/icons-material/RestaurantOutlined'
import ShoppingBagOutlinedIcon from '@mui/icons-material/ShoppingBagOutlined'
import StarRoundedIcon from '@mui/icons-material/StarRounded'
import type { Order, OrderType } from '../api/orders'
import {
  formatDuration,
  formatItems,
  formatMinutesUntil,
  formatTime,
  ORDER_TYPE_HINT,
  ORDER_TYPE_LABEL,
} from '../format'
import { BADGE } from '../theme'
import { numeric } from './tableStyles'

const ORDER_TYPE_ICON: Record<OrderType, typeof RestaurantOutlinedIcon> = {
  dine_in: RestaurantOutlinedIcon,
  takeout: ShoppingBagOutlinedIcon,
  delivery: DeliveryDiningOutlinedIcon,
}

/** A quiet badge: tinted background, darker text, hairline border. */
export function Badge({ tone, icon, children }: { tone: keyof typeof BADGE; icon?: ReactNode; children: ReactNode }) {
  const c = BADGE[tone]
  return (
    <Box
      component="span"
      sx={{
        display: 'inline-flex',
        alignItems: 'center',
        gap: 0.5,
        px: 1,
        py: 0.25,
        borderRadius: 999,
        fontSize: 12,
        fontWeight: 700,
        lineHeight: 1.6,
        whiteSpace: 'nowrap',
        color: c.fg,
        bgcolor: c.bg,
        border: 1,
        borderColor: c.border,
      }}
    >
      {icon}
      {children}
    </Box>
  )
}

/** Customer name first (what people say out loud), order number beside it. */
export function OrderCell({ order }: { order: Order }) {
  return (
    <Box sx={{ whiteSpace: 'nowrap' }}>
      <Typography component="span" sx={{ fontWeight: 700 }}>
        {order.customer_name}
      </Typography>
      <Typography component="span" variant="body2" color="text.secondary" sx={{ ml: 1 }}>
        #{order.id}
      </Typography>
    </Box>
  )
}

/** A VIP badge for VIP customers; nothing otherwise, so only the exception stands out. */
export function VipCell({ isVip }: { isVip: boolean }) {
  if (!isVip) return <span aria-label="Not VIP" />
  return (
    <Badge tone="vip" icon={<StarRoundedIcon sx={{ fontSize: 14 }} aria-hidden />}>
      VIP
    </Badge>
  )
}

/** Icon + "Delivery"; the meaning ("goes out with a courier") on hover. */
export function TypeCell({ type }: { type: OrderType }) {
  const Icon = ORDER_TYPE_ICON[type]
  return (
    <Tooltip title={ORDER_TYPE_HINT[type]} placement="top">
      <Stack direction="row" alignItems="center" spacing={0.75} sx={{ width: 'fit-content' }}>
        <Icon sx={{ fontSize: 18, color: 'text.secondary' }} aria-hidden />
        <Typography variant="body2">{ORDER_TYPE_LABEL[type]}</Typography>
      </Stack>
    </Tooltip>
  )
}

/** One-line summary ("2× Grilled Salmon, 1× Caesar Salad"); the full list on hover if it is cut. */
export function ItemsCell({ order }: { order: Order }) {
  return (
    <Tooltip
      placement="top-start"
      title={
        <Box component="ul" sx={{ m: 0, pl: 2 }}>
          {order.items.map((item) => (
            <li key={item.menu_item_id}>
              {item.quantity}× {item.name}
            </li>
          ))}
        </Box>
      }
    >
      <Typography variant="body2" noWrap sx={{ maxWidth: 260 }}>
        {formatItems(order.items)}
      </Typography>
    </Tooltip>
  )
}

/** A duration from the API ("1 h 25 min"), with its context ("Placed at 10:10") on hover. */
export function DurationCell({ minutes, detail }: { minutes: number; detail: string }) {
  return (
    <Tooltip title={detail} placement="top">
      <Typography variant="body2" sx={{ ...numeric, width: 'fit-content' }}>
        {formatDuration(minutes)}
      </Typography>
    </Tooltip>
  )
}

/** "11:45 · in 9 min", the lateness in red; a quiet dash when nothing was promised. */
export function PromisedCell({ order }: { order: Order }) {
  if (order.promised_at === null || order.minutes_until_promised === null) {
    return (
      <Typography variant="body2" color="text.secondary" aria-label="No promised time">
        —
      </Typography>
    )
  }
  const late = order.minutes_until_promised < 0
  return (
    <Typography variant="body2" sx={numeric}>
      {formatTime(order.promised_at)}
      <Box component="span" sx={{ ml: 0.75, color: late ? 'error.main' : 'text.secondary', fontWeight: late ? 700 : 400 }}>
        · {formatMinutesUntil(order.minutes_until_promised)}
      </Box>
    </Typography>
  )
}

