import { Button, IconButton, Stack, Tooltip } from '@mui/material'
import CloseRoundedIcon from '@mui/icons-material/CloseRounded'
import type { Order, OrderAction } from '../api/orders'
import { ACTION_LABEL } from '../format'

interface OrderActionsProps {
  order: Order
  disabled: boolean
  /** The one order the eye should go to (Next up) gets a filled button; the rest are quieter. */
  emphasized?: boolean
  onAction: (order: Order, action: OrderAction) => void
}

/**
 * Renders exactly the actions the API lists in `allowed_actions` — the state machine lives on
 * the server, so a status change there needs no change here. The step forward is a button with
 * a fixed width (buttons line up row to row); cancelling is a small icon with its name on hover,
 * and it still asks for confirmation.
 */
export function OrderActions({ order, disabled, emphasized = false, onAction }: OrderActionsProps) {
  const forward = order.allowed_actions.filter((action) => action !== 'cancel')
  const canCancel = order.allowed_actions.includes('cancel')

  return (
    <Stack direction="row" spacing={0.5} alignItems="center">
      {forward.map((action) => (
        <Button
          key={action}
          size="small"
          variant={emphasized ? 'contained' : 'outlined'}
          disabled={disabled}
          onClick={() => onAction(order, action)}
          aria-label={`${ACTION_LABEL[action]}: order ${order.id}`}
          sx={{ width: 136, whiteSpace: 'nowrap', ...(!emphasized && { bgcolor: 'background.paper' }) }}
        >
          {ACTION_LABEL[action]}
        </Button>
      ))}
      {canCancel && (
        <Tooltip title={ACTION_LABEL.cancel}>
          <span>
            <IconButton
              size="small"
              disabled={disabled}
              onClick={() => onAction(order, 'cancel')}
              aria-label={`${ACTION_LABEL.cancel}: order ${order.id}`}
