import type { ReactNode } from 'react'
import { Box, ButtonBase, Chip, Stack, Typography } from '@mui/material'
import ChevronRightRoundedIcon from '@mui/icons-material/ChevronRightRounded'
import WarningAmberRoundedIcon from '@mui/icons-material/WarningAmberRounded'
import type { View } from '../format'
import { VIEW_HINT, VIEW_LABEL } from '../format'

interface StatusPipelineProps {
  value: View
  counts: Partial<Record<View, number>> // missing = not loaded yet
  lateOrderIds: number[]
  onChange: (view: View) => void
}

/**
 * The one control for choosing what the table shows, laid out as the path an order takes:
 * Received → Preparing → Ready → Finished. "All active", "Received" and "Preparing" are the
 * spec's queue filter (§8); "Ready" and "Finished" are the views after the kitchen.
 * Counts are lengths of lists the API returned.
 */
export function StatusPipeline({ value, counts, lateOrderIds, onChange }: StatusPipelineProps) {
  const step = (view: View) => (
    <PipelineStep key={view} view={view} selected={value === view} count={counts[view]} onSelect={onChange} />
  )
  const arrow = (key: string) => (
    <ChevronRightRoundedIcon key={key} sx={{ color: 'text.disabled', alignSelf: 'center', mt: 2.5 }} aria-hidden />
  )

  return (
    <Stack
      direction="row"
      alignItems="flex-start"
      justifyContent="space-between"
      flexWrap="wrap"
      useFlexGap
      sx={{ px: 2, pt: 2, gap: 2 }}
    >
      <Stack direction="row" alignItems="flex-start" spacing={2} role="group" aria-label="Show orders">
        <Group label="Kitchen queue">
          {step('active')}
          <Box sx={{ width: 8 }} />
          {step('received')}
          {arrow('a1')}
          {step('preparing')}
        </Group>
        {arrow('a2')}
        <Group label="After the kitchen">
          {step('ready')}
          {arrow('a3')}
          {step('finished')}
        </Group>
      </Stack>

      {lateOrderIds.length > 0 && (
        <Chip
          icon={<WarningAmberRoundedIcon />}
          color="error"
          variant="outlined"
          sx={{ mt: 2.5, bgcolor: 'background.paper' }}
          label={`Promised time passed: ${lateOrderIds.map((id) => `#${id}`).join(', ')}`}
        />
      )}
    </Stack>
  )
}

function Group({ label, children }: { label: string; children: ReactNode }) {
  return (
    <Box>
      <Typography
        variant="caption"
        component="div"
        color="text.secondary"
        sx={{ fontWeight: 800, textTransform: 'uppercase', letterSpacing: 0.5, mb: 0.5 }}
      >
        {label}
      </Typography>
      <Stack direction="row" alignItems="stretch">
        {children}
      </Stack>
    </Box>
  )
}

function PipelineStep({
  view,
  selected,
  count,
  onSelect,
}: {
  view: View
  selected: boolean
  count: number | undefined
  onSelect: (view: View) => void
}) {
  return (
    <ButtonBase
      onClick={() => onSelect(view)}
      aria-pressed={selected}
      aria-label={`${VIEW_LABEL[view]}${count === undefined ? '' : `, ${count} orders`}`}
      sx={{
        display: 'block',
        textAlign: 'left',
        minWidth: 116,
        px: 1.5,
        py: 1,
        borderRadius: 2,
        border: 2,
        borderColor: selected ? 'primary.main' : 'divider',
        bgcolor: selected ? 'rgba(0, 124, 153, 0.08)' : 'background.paper',
        '&:hover': { borderColor: 'primary.main' },
      }}
    >
      <Stack direction="row" alignItems="baseline" spacing={1}>
        <Typography sx={{ fontWeight: 800, color: 'text.primary' }}>{VIEW_LABEL[view]}</Typography>
        {count !== undefined && (
          <Typography sx={{ fontWeight: 800, fontVariantNumeric: 'tabular-nums', color: 'text.secondary' }}>{count}</Typography>
        )}
      </Stack>
      <Typography variant="caption" color="text.secondary" component="div">
        {VIEW_HINT[view]}
      </Typography>
    </ButtonBase>
  )
}

