import { AppBar, Box, Button, CircularProgress, Stack, Toolbar, Tooltip, Typography } from '@mui/material'
import HelpOutlineRoundedIcon from '@mui/icons-material/HelpOutlineRounded'
import RefreshRoundedIcon from '@mui/icons-material/RefreshRounded'
import RestaurantMenuRoundedIcon from '@mui/icons-material/RestaurantMenuRounded'
import { formatAgo, formatTime } from '../format'
import { useNow } from '../hooks/useNow'
import { BRAND } from '../theme'

const HOW_IT_WORKS =
  'Orders move Received → Preparing → Ready → Finished. The kitchen queue is ranked by priority: ' +
  'start the order marked “Next up”. Hover a position number to see why an order is there.'

interface AppHeaderProps {
  generatedAt: string | null // when the API computed the data on screen
  refreshing: boolean
  offline: boolean // the last refresh failed
  autoRefreshSeconds: number
  onRefresh: () => void
}

/** A slim bar: product name, a "how it works" hint, the live clock and how fresh the data is. */
export function AppHeader({ generatedAt, refreshing, offline, autoRefreshSeconds, onRefresh }: AppHeaderProps) {
  const now = useNow(1000)

  return (
    <AppBar position="static" color="inherit" elevation={0} sx={{ borderBottom: 1, borderColor: 'divider' }}>
      <Toolbar variant="dense" sx={{ gap: 1.5, minHeight: 56 }}>
        <Box
          sx={{
            width: 30,
            height: 30,
            borderRadius: 1.5,
            bgcolor: BRAND.navy,
            color: BRAND.cyan,
            display: 'grid',
            placeItems: 'center',
            flexShrink: 0,
          }}
          aria-hidden
        >
          <RestaurantMenuRoundedIcon sx={{ fontSize: 18 }} />
        </Box>
        <Typography component="h1" sx={{ fontWeight: 800, fontSize: 16 }}>
          Kitchen Display
        </Typography>
        <Tooltip title={HOW_IT_WORKS}>
          <HelpOutlineRoundedIcon sx={{ fontSize: 18, color: 'text.secondary', cursor: 'help' }} aria-label={HOW_IT_WORKS} />
        </Tooltip>

        <Box sx={{ flexGrow: 1 }} />

        <FreshnessIndicator generatedAt={generatedAt} now={now} offline={offline} autoRefreshSeconds={autoRefreshSeconds} />
        <Typography sx={{ fontVariantNumeric: 'tabular-nums', fontWeight: 700, fontSize: 15, minWidth: 72, textAlign: 'right' }}>
          {formatTime(now.toISOString(), true)}
        </Typography>
        <Button
          variant="outlined"
          size="small"
          color="inherit"
          onClick={onRefresh}
          disabled={refreshing}
          startIcon={refreshing ? <CircularProgress size={14} color="inherit" /> : <RefreshRoundedIcon />}
          sx={{ flexShrink: 0, minWidth: 112, borderColor: 'divider' }}
        >
          {refreshing ? 'Refreshing…' : 'Refresh'}
        </Button>
      </Toolbar>
    </AppBar>
  )
