/** "● Live · updated 4 s ago" (green), or "● Offline · retrying" (red) when the last refresh failed. */
function FreshnessIndicator({
  generatedAt,
  now,
  offline,
  autoRefreshSeconds,
}: {
  generatedAt: string | null
  now: Date
  offline: boolean
  autoRefreshSeconds: number
}) {
  const text = offline
    ? `Offline · retrying every ${autoRefreshSeconds} s`
    : generatedAt
      ? `Live · updated ${formatAgo(new Date(generatedAt), now)}`
      : 'Connecting…'

  return (
    <Stack direction="row" alignItems="center" spacing={0.75} aria-live="polite">
      <Box
        sx={{
          width: 8,
          height: 8,
          borderRadius: '50%',
          bgcolor: offline ? 'error.main' : '#2e9d5b',
          // A slow pulse says "this updates by itself"; respects reduced-motion preferences.
          '@media (prefers-reduced-motion: no-preference)': {
            animation: offline ? 'none' : 'pulse 2s ease-in-out infinite',
          },
          '@keyframes pulse': { '0%, 100%': { opacity: 1 }, '50%': { opacity: 0.35 } },
        }}
      />
      <Typography variant="body2" color="text.secondary" sx={{ whiteSpace: 'nowrap' }}>
        {text}
      </Typography>
    </Stack>
  )
}

