// Presentation only: labels, colors and text formatting. No business rules live here —
// which actions exist for an order, its score, its position and every time value come from the API.
import type { OrderAction, OrderItem, OrderStatus, OrderType, QueueFilter } from './api/orders'

export const ORDER_TYPE_LABEL: Record<OrderType, string> = {
  dine_in: 'Dine-in',
  takeout: 'Takeout',
  delivery: 'Delivery',
}

/** Where the food goes — answers "who is this order for?" at a glance. */
export const ORDER_TYPE_HINT: Record<OrderType, string> = {
  dine_in: 'eats in the restaurant',
  takeout: 'customer picks up',
  delivery: 'goes out with a courier',
}

export const STATUS_LABEL: Record<OrderStatus, string> = {
  received: 'Received',
  preparing: 'Preparing',
  ready: 'Ready',
  picked_up: 'Picked up',
  cancelled: 'Cancelled',
}

/** Badge tone per status: colour only tells states apart, it carries no extra meaning. */
export const STATUS_TONE: Record<OrderStatus, 'info' | 'warning' | 'success' | 'neutral'> = {
  received: 'info',
  preparing: 'warning',
  ready: 'success',
  picked_up: 'neutral',
  cancelled: 'neutral',
}

/**
 * What the table shows. One word per status everywhere on the screen (the spec's own words):
 * "active", "received" and "preparing" are the spec's queue filter (§8); "ready" and "finished"
 * are the views after the kitchen.
 */
export type View = QueueFilter | 'ready' | 'finished'

export const VIEW_LABEL: Record<View, string> = {
  active: 'All active',
  received: STATUS_LABEL.received,
  preparing: STATUS_LABEL.preparing,
  ready: STATUS_LABEL.ready,
  finished: 'Finished',
}

/** The line under each view's name: what an order in it is waiting for. */
export const VIEW_HINT: Record<View, string> = {
  active: 'received + preparing',
  received: 'not started yet',
  preparing: 'in the kitchen',
  ready: 'waiting for pickup',
  finished: 'picked up or cancelled',
}

/** Button text: the step it takes, ending in the status it leads to. */
export const ACTION_LABEL: Record<OrderAction, string> = {
  start: 'Start preparing',
  ready: 'Mark ready',
  pickup: 'Mark picked up',
  cancel: 'Cancel order',
}

/** Shown after a successful action: the new status and where the order can now be found. */
export function describeNewStatus(orderId: number, status: OrderStatus): string {
  switch (status) {
    case 'preparing':
      return `Order #${orderId} is now Preparing.`
    case 'ready':
      return `Order #${orderId} is now Ready. Find it under “Ready”.`
    case 'picked_up':
      return `Order #${orderId} was Picked up. Find it under “Finished”.`
    case 'cancelled':
      return `Order #${orderId} was Cancelled. Find it under “Finished”.`
    default:
      return `Order #${orderId} is now ${STATUS_LABEL[status]}.`
  }
}

export const EMPTY_MESSAGE: Record<View, string> = {
  active: 'No active orders. The kitchen is clear.',
  received: 'No Received orders: nothing waiting to be started.',
  preparing: 'No orders are Preparing right now.',
  ready: 'No Ready orders: nothing waiting for pickup.',
  finished: 'No Finished orders yet.',
}

/** "2× Grilled Salmon, 1× Caesar Salad" — a non-breaking space keeps "2×" on the dish's line. */
export function formatItems(items: OrderItem[]): string {
  return items.map((item) => `${item.quantity}× ${item.name}`).join(', ')
}

/** Local wall-clock time, e.g. "14:35" (or "14:35:08" with seconds). */
export function formatTime(isoTimestamp: string, withSeconds = false): string {
  return new Date(isoTimestamp).toLocaleTimeString([], {
    hour: '2-digit',
    minute: '2-digit',
    ...(withSeconds && { second: '2-digit' }),
  })
}

/** "just now", "12 s ago", "3 min ago" — for the freshness indicator. */
export function formatAgo(from: Date, now: Date): string {
  const seconds = Math.max(0, Math.round((now.getTime() - from.getTime()) / 1000))
  if (seconds < 3) return 'just now'
  if (seconds < 60) return `${seconds} s ago`
  return `${Math.floor(seconds / 60)} min ago`
}

/** "45 min", "2 h", "2 h 59 min" */
export function formatDuration(minutes: number): string {
  if (minutes < 60) return `${minutes} min`
  const hours = Math.floor(minutes / 60)
  const rest = minutes % 60
  return rest === 0 ? `${hours} h` : `${hours} h ${rest} min`
}

/** The API's minutes_until_promised as text: "in 20 min", "in 2 h 59 min", "due now", "5 min late". */
export function formatMinutesUntil(minutes: number): string {
  if (minutes > 0) return `in ${formatDuration(minutes)}`
  if (minutes === 0) return 'due now'
  return `${formatDuration(-minutes)} late`
}

