  cancelled: 'Cancelled',
}

/** Badge tone per status: colour only tells states apart, it carries no extra meaning. */
export const STATUS_TONE: Record<OrderStatus, 'info' | 'warning' | 'success' | 'neutral'> = {
  received: 'info',
  preparing: 'warning',
  ready: 'success',
  picked_up: 'neutral',
