}

/**
 * The reasons this order is where it is, in a cook's words. A part of the score is listed only
 * if the API says it actually raised the priority (points > 0). No points are shown: the screen
 * explains the ranking, it does not expose the formula.
 */
function reasonsFor(order: Order): string[] {
  const minutes = order.minutes_until_promised
  const reasons: Record<keyof ScoreBreakdown, string> = {
    type: `${ORDER_TYPE_LABEL[order.type]} order`,
    vip: 'VIP customer',
    wait: `Waiting for ${formatDuration(order.wait_minutes)}`,
