// Simulates the API after a live change the UI has never heard of, and checks the screen survives.
import { chromium } from 'playwright-core'

const OUT = process.argv[2]
let failures = 0
const check = (label, ok, extra = '') => { if (!ok) failures++; console.log(`${ok ? 'PASS' : 'FAIL'}  ${label}${extra ? `  — ${extra}` : ''}`) }

const browser = await chromium.launch({ channel: 'msedge', headless: true })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
const pageErrors = []
page.on('pageerror', (e) => pageErrors.push(e.message))

// Rewrite the queue response: order #3 gets a new status, type, action, score part and tie-break.
await page.route('**/orders/queue', async (route) => {
  const response = await route.fetch()
  const body = await response.json()
  const target = body.orders.find((o) => o.id === 3)
  Object.assign(target, {
    status: 'on_hold',
    type: 'catering',
    allowed_actions: ['hold', 'cancel'],
    score_breakdown: { ...target.score_breakdown, allergy: 10 },
    ahead_of_next: { order_id: body.orders[body.orders.indexOf(target) + 1].id, decided_by: 'is_vip' },
  })
  await route.fulfill({ response, json: body })
})

await page.goto('http://localhost:5173')
await page.locator('tbody tr').first().waitFor()
await page.waitForTimeout(500)
const row = page.locator('tbody tr', { has: page.locator('span', { hasText: /^#3$/ }) })
const rowText = (await row.innerText()).replace(/\s+/g, ' ')

check('no JavaScript error on the page', pageErrors.length === 0, pageErrors.join(' | '))
check('no "list could not be displayed" fallback needed', (await page.getByText('This list could not be displayed').count()) === 0)
check('unknown status shows as a readable badge', rowText.includes('On hold'), rowText)
