=================== src/modules/priority.js
// Priority score for the kitchen queue (spec §5.1).
// Pure: everything it needs arrives as arguments, including `now`. No clock, no database.

const MS_PER_MINUTE = 60 * 1000;

// Every tunable number of the ranking lives here, so a product change to the
// ranking is a one-place edit (plus its test).
const PRIORITY_RULES = {
  typePoints: { dine_in: 30, takeout: 20, delivery: 10 },
  vipPoints: 20,
  wait: { stepMinutes: 10, pointsPerStep: 5, max: 40 },
  // Checked in order: the first bucket that covers the minutes left wins.
  // A promise further away than every bucket, or no promise at all, scores 0.
  promised: [
    { upToMinutes: 30, points: 25 },
    { upToMinutes: 60, points: 15 },
  ],
  complexity: { stepMinutes: 15, pointsPerStep: 5, max: 20 },
};

// Whole minutes from `from` to `to`, floored (9m50s -> 9). Negative when `to` is earlier.
function wholeMinutesBetween(from, to) {
  return Math.floor((new Date(to).getTime() - new Date(from).getTime()) / MS_PER_MINUTE);
}

// Clamped at 0 so an order with a placed_at slightly in the future (clock skew) is not penalized.
function minutesWaiting(placedAt, now) {
  return Math.max(0, wholeMinutesBetween(placedAt, now));
}

function totalPrepMinutes(items) {
  return items.reduce((sum, item) => sum + item.prep_time_minutes * item.quantity, 0);
}

// min(max, floor(value / step) * pointsPerStep) -- shared by wait time and complexity.
function steppedPoints(value, { stepMinutes, pointsPerStep, max }) {
  return Math.min(max, Math.floor(value / stepMinutes) * pointsPerStep);
}

// Whole minutes from `now` until the promise, floored like minutes_waiting; negative once
// overdue; null when there is no promise.
function minutesUntilPromised(promisedAt, now) {
  return promisedAt == null ? null : wholeMinutesBetween(now, promisedAt);
}

// Whole minutes make the spec's "0-30" and "31-60" buckets gapless (30m59s -> 30 -> top bucket).
// An overdue promise is negative and lands in the top bucket: the spec only gives 0 to
// "more than 60 minutes away or null".
function promisedPoints(promisedAt, now, buckets) {
  const minutesLeft = minutesUntilPromised(promisedAt, now);
  if (minutesLeft === null) return 0;
  const bucket = buckets.find((b) => minutesLeft <= b.upToMinutes);
  return bucket ? bucket.points : 0;
}

function typePoints(type, pointsByType) {
  const points = pointsByType[type];
  // Fail loudly: a new order type without a weight is a bug, not a silent 0.
  if (points === undefined) throw new Error(`No priority weight for order type "${type}"`);
  return points;
}

/**
 * The points each input of the formula contributes. Plain numbers, no text: wording belongs to
 * the UI. The score is their sum, so the two can never disagree. Pure, like computeScore.
 * @returns {{ type: number, vip: number, wait: number, promise: number, complexity: number }}
 */
function scoreBreakdown(order, now, rules = PRIORITY_RULES) {
  return {
    type: typePoints(order.type, rules.typePoints),
    vip: order.is_vip ? rules.vipPoints : 0,
    wait: steppedPoints(minutesWaiting(order.placed_at, now), rules.wait),
    promise: promisedPoints(order.promised_at, now, rules.promised),
    complexity: steppedPoints(totalPrepMinutes(order.items), rules.complexity),
  };
}

/**
 * The priority score (spec §5.1): the sum of the points above.
 * @param {object} order  { type, is_vip, placed_at, promised_at, items: [{ prep_time_minutes, quantity }] }
 * @param {Date} now      the moment the queue is computed (real clock in the app, frozen in tests)
 * @param {object} [rules] scoring weights; defaults to PRIORITY_RULES
 * @returns {number}
 */
function computeScore(order, now, rules = PRIORITY_RULES) {
  const points = scoreBreakdown(order, now, rules);
  return points.type + points.vip + points.wait + points.promise + points.complexity;
}

module.exports = { PRIORITY_RULES, computeScore, scoreBreakdown, minutesWaiting, minutesUntilPromised };
=================== src/modules/queue.js
// The active queue: which statuses it shows and in what order (spec §5, §5.2). Pure: no database.
const { AppError } = require('../errors');
const { computeScore, scoreBreakdown, minutesWaiting, minutesUntilPromised } = require('./priority');
const { allowedActions } = require('./transitions');

// ready, picked_up and cancelled orders stay out of the active queue.
const ACTIVE_STATUSES = ['received', 'preparing'];

// No filter -> the whole active queue; `?status=` may only narrow it to one active status.
function resolveQueueStatuses(statusFilter) {
  if (statusFilter === undefined) return [...ACTIVE_STATUSES]; // a copy: callers cannot mutate the rule
  if (ACTIVE_STATUSES.includes(statusFilter)) return [statusFilter];
  throw new AppError(
    'INVALID_STATUS_FILTER',
    `status must be one of: ${ACTIVE_STATUSES.join(', ')}.`,
    { status: statusFilter, allowed: ACTIVE_STATUSES },
  );
}

// Earlier time first; a missing time (null) goes last.
function compareTimesNullLast(a, b) {
  if (a == null && b == null) return 0;
  if (a == null) return 1;
  if (b == null) return -1;
  return new Date(a).getTime() - new Date(b).getTime();
}

// The queue order (spec §5.1 then §5.2), one named criterion per line. The sort uses this list,
// and so does decidedBy, so a new or reordered tie-break is a one-place change.
const QUEUE_ORDER = [
  { name: 'score', compare: (a, b) => b.score - a.score },
  { name: 'promised_at', compare: (a, b) => compareTimesNullLast(a.promised_at, b.promised_at) },
  { name: 'placed_at', compare: (a, b) => compareTimesNullLast(a.placed_at, b.placed_at) },
  { name: 'id', compare: (a, b) => a.id - b.id },
];

// Highest score first, then the tie-breaks: the first criterion that is not a tie decides.
function compareQueue(a, b) {
  for (const criterion of QUEUE_ORDER) {
    const result = criterion.compare(a, b);
    if (result !== 0) return result;
  }
  return 0;
}

// Which criterion puts `a` above `b` (e.g. 'promised_at' when their scores tie). Data only; the
// UI turns it into words.
function decidedBy(a, b) {
  return QUEUE_ORDER.find((criterion) => criterion.compare(a, b) !== 0)?.name ?? null;
}

// The order plus the values computed at request time. Never stored: they depend on `now`.
// The minute fields use the same `now` as the score, so the UI can display time without
// keeping a clock or any time rule of its own.
function withComputedFields(order, now) {
  return {
    ...order,
    score: computeScore(order, now),
    score_breakdown: scoreBreakdown(order, now),
    wait_minutes: minutesWaiting(order.placed_at, now),
    minutes_until_promised: minutesUntilPromised(order.promised_at, now),
    minutes_in_status: minutesWaiting(order.status_changed_at, now),
    allowed_actions: allowedActions(order.status),
  };
}

// Returns the orders in queue order, each with its computed fields and, except for the last one,
// which criterion placed it above the next order.
function rankQueue(orders, now) {
  const ranked = orders.map((order) => withComputedFields(order, now)).sort(compareQueue);
  return ranked.map((order, index) => {
    const next = ranked[index + 1];
    return { ...order, ahead_of_next: next ? { order_id: next.id, decided_by: decidedBy(order, next) } : null };
  });
}

module.exports = { ACTIVE_STATUSES, resolveQueueStatuses, compareQueue, decidedBy, withComputedFields, rankQueue };
=================== src/modules/transitions.js
// Order status state machine (spec §6). Pure: no database.
const { AppError } = require('../errors');

// The only legal moves. Anything not listed is rejected: skipping a step,
// repeating the current status, or leaving a terminal status (picked_up, cancelled).
// `from` is a list so allowing an action from another status is a one-word change.
const TRANSITIONS = {
  start: { from: ['received'], to: 'preparing' },
  ready: { from: ['preparing'], to: 'ready' },
  pickup: { from: ['ready'], to: 'picked_up' },
  cancel: { from: ['received'], to: 'cancelled' },
};

// Returns the status the order moves to, or throws INVALID_TRANSITION.
function resolveTransition(currentStatus, action) {
  const rule = TRANSITIONS[action];
  if (!rule) throw new Error(`Unknown transition action "${action}"`);

  if (!rule.from.includes(currentStatus)) {
    throw new AppError(
      'INVALID_TRANSITION',
      `Cannot ${action} an order that is ${currentStatus}.`,
      { action, current_status: currentStatus, allowed_from: rule.from },
    );
  }
  return rule.to;
}

// Actions the expeditor may take from `status`. Sent with every order in the API
// response so the UI shows buttons without keeping its own copy of these rules.
function allowedActions(status) {
  return Object.keys(TRANSITIONS).filter((action) => TRANSITIONS[action].from.includes(status));
}

module.exports = { TRANSITIONS, resolveTransition, allowedActions };
=================== src/modules/orders.module.js
// Use cases for the expeditor screen. Applies the pure rules (queue, transitions) to data
// loaded through the repository. Knows nothing about HTTP.
const { AppError } = require('../errors');
const repository = require('../repositories/orders.repository');
const { resolveQueueStatuses, rankQueue, withComputedFields } = require('./queue');
const { resolveTransition } = require('./transitions');

// Views next to the active queue (which is ranked by score, see queue.js):
// - ready: waiting for pickup, the one waiting longest first;
// - finished: the most recent first, capped, because the screen shows recent history, not an archive.
const READY_STATUSES = ['ready'];
const FINISHED_STATUSES = ['picked_up', 'cancelled'];
const FINISHED_LIMIT = 20;

async function getQueue({ status, now }) {
  const statuses = resolveQueueStatuses(status);
  const orders = await repository.findOrdersByStatuses(statuses);
  return rankQueue(orders, now);
}

async function getReadyOrders({ now }) {
  const orders = await repository.findOrdersByStatuses(READY_STATUSES, { byStatusChange: 'ASC' });
  return orders.map((order) => withComputedFields(order, now));
}

async function getFinishedOrders({ now }) {
  const orders = await repository.findOrdersByStatuses(FINISHED_STATUSES, {
    byStatusChange: 'DESC',
    limit: FINISHED_LIMIT,
  });
  return orders.map((order) => withComputedFields(order, now));
}

const orderNotFound = (id) => new AppError('ORDER_NOT_FOUND', `Order ${id} does not exist.`, { id });

async function transitionOrder({ id, action, now }) {
  const order = await repository.findOrderById(id);
  if (!order) throw orderNotFound(id);

  const nextStatus = resolveTransition(order.status, action); // throws INVALID_TRANSITION

  const moved = await repository.updateStatusIfCurrent(id, order.status, nextStatus, now);
  if (!moved) {
    // The status changed between our read and our write: another request won the race.
    const current = await repository.findOrderById(id);
    if (!current) throw orderNotFound(id);
    throw new AppError(
      'INVALID_TRANSITION',
      `Order ${id} was changed to ${current.status} by another request.`,
      { action, current_status: current.status },
    );
  }

  return withComputedFields({ ...order, status: nextStatus, status_changed_at: now }, now);
}

module.exports = { FINISHED_LIMIT, getQueue, getReadyOrders, getFinishedOrders, transitionOrder };

