// Renders README.md roughly as GitHub does (github-markdown-css + Mermaid) and screenshots it.
import { readFileSync } from 'node:fs'
import { pathToFileURL } from 'node:url'
import { chromium } from 'playwright-core'

const [repo, out] = process.argv.slice(2)
const markdown = readFileSync(`${repo}/README.md`, 'utf8')

const html = `<!doctype html><html><head><meta charset="utf-8">
<base href="${pathToFileURL(repo + '/').href}">
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/github-markdown-css@5/github-markdown-light.css">
<style>body{background:#fff;margin:0} .markdown-body{max-width:1012px;margin:0 auto;padding:40px 45px}</style>
<script src="https://cdn.jsdelivr.net/npm/marked@12/marked.min.js"></script>
<script src="https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js"></script>
</head><body><article class="markdown-body" id="c"></article>
<script>
  const md = ${JSON.stringify(markdown)};
  document.getElementById('c').innerHTML = marked.parse(md);
  document.querySelectorAll('code.language-mermaid').forEach((el) => {
    const div = document.createElement('div'); div.className = 'mermaid'; div.textContent = el.textContent;
    el.parentElement.replaceWith(div);
  });
  document.querySelectorAll('details').forEach((d) => (d.open = true));
  mermaid.initialize({ startOnLoad: false });
  mermaid.run().then(() => (window.done = 'ok')).catch((e) => (window.done = 'mermaid error: ' + e.message));
</script></body></html>`

const browser = await chromium.launch({ channel: 'msedge', headless: true })
const page = await browser.newPage({ viewport: { width: 1100, height: 900 } })
await page.setContent(html, { waitUntil: 'networkidle' })
await page.waitForFunction(() => window.done, null, { timeout: 30000 })
console.log('mermaid:', await page.evaluate(() => window.done))
console.log('diagrams rendered:', await page.locator('.mermaid svg').count())
console.log('broken images:', await page.evaluate(() => [...document.images].filter((i) => !i.complete || i.naturalWidth === 0).map((i) => i.getAttribute('src'))))
const height = await page.evaluate(() => document.body.scrollHeight)
console.log('page height:', height)
for (let i = 0, y = 0; y < height; i++, y += 1800) {
  await page.screenshot({ path: `${out}/readme-${i}.png`, clip: { x: 0, y, width: 1100, height: Math.min(1800, height - y) } })
}
await browser.close()

