import { expect, test } from '@playwright/test'
import type { APIRequestContext } from '@playwright/test'

const API_URL = 'http://localhost:4000'
const AUTO_REFRESH_TIMEOUT = 20_000

async function createOrder(request: APIRequestContext, customerName: string): Promise<number> {
  const response = await request.post(`${API_URL}/orders`, {
    data: {
      customer_name: customerName,
      type: 'takeout',
      is_vip: false,
      promised_at: null,
      items: [{ menu_item_id: 1, quantity: 1 }],
    },
  })
  expect(response.status()).toBe(201)
  const { order } = await response.json()
  return order.id
}

// Takes the order out of the active queue so repeated runs keep the demo data readable.
async function finishOrder(request: APIRequestContext, id: number) {
  for (const action of ['ready', 'pickup']) {
    await request.post(`${API_URL}/orders/${id}/${action}`)
  }
}

const uniqueName = (label: string) => `${label} ${Date.now().toString(36)}`

test('an order created through the API appears on the open screen', async ({ page, request }) => {
  await page.goto('/')
