const fs = require('fs');

const jsonHeader = [{ key: 'Content-Type', value: 'application/json' }];

function url(path, query) {
  return {
    raw: `{{baseUrl}}${path}${query ? '?' + query.map(([k, v]) => `${k}=${v}`).join('&') : ''}`,
    host: ['{{baseUrl}}'],
    path: path.split('/').filter(Boolean),
    ...(query && { query: query.map(([key, value]) => ({ key, value })) }),
  };
}

const expectCode = (code) =>
  `pm.test('error code ${code}', () => pm.expect(pm.response.json().error.code).to.eql('${code}'));`;
const expectOrderStatus = (status) =>
  `pm.test('order is ${status}', () => pm.expect(pm.response.json().order.status).to.eql('${status}'));`;
const saveId = (variable) => `pm.collectionVariables.set('${variable}', pm.response.json().order.id);`;

function request(name, method, path, { query, body, rawBody, status, tests = [], description } = {}) {
  const raw = rawBody ?? (body === undefined ? undefined : JSON.stringify(body, null, 2));
  return {
    name,
    event: [
      {
        listen: 'test',
        script: {
          type: 'text/javascript',
          exec: [`pm.test('status ${status}', () => pm.response.to.have.status(${status}));`, ...tests],
        },
      },
    ],
    request: {
      method,
      header: raw === undefined ? [] : jsonHeader,
      ...(raw !== undefined && { body: { mode: 'raw', raw, options: { raw: { language: 'json' } } } }),
      url: url(path, query),
      ...(description && { description }),
    },
  };
}

const newOrder = (customer_name, extra = {}) => ({
  customer_name,
  type: 'takeout',
  is_vip: false,
  promised_at: null,
  items: [
    { menu_item_id: 3, quantity: 2 },
    { menu_item_id: 1, quantity: 1 },
  ],
  ...extra,
});

const collection = {
  info: {
    name: 'Kitchen Queue API',
    description:
      'Every endpoint of the Kitchen Queue API, with status checks. Run `npm run db:setup` and `npm run dev` first.\n\n' +
      'Menu item ids follow the seed: 1 Caesar Salad, 3 Grilled Salmon, 4 Margherita Pizza, 5 Ribeye Steak.\n\n' +
      'Run the whole collection in order with the Collection Runner: "2. Create" saves the order ids that "3. Lifecycle" and "4. Cancel" use.',
    schema: 'https://schema.getpostman.com/json/collection/v2.1.0/collection.json',
  },
  variable: [
    { key: 'baseUrl', value: 'http://localhost:4000' },
    { key: 'orderId', value: '' },
    { key: 'cancelOrderId', value: '' },
  ],
  item: [
    {
      name: '1. Queue',
      item: [
        request('Active queue (received + preparing)', 'GET', '/orders/queue', {
          status: 200,
          tests: [
            "pm.test('sorted by score, highest first', () => { const scores = pm.response.json().orders.map((o) => o.score); pm.expect(scores).to.eql([...scores].sort((a, b) => b - a)); });",
          ],
          description:
            'Ranked by score, then promised_at (null last), placed_at and id. Each order carries score, score_breakdown, allowed_actions and ahead_of_next.',
        }),
        request('Only received', 'GET', '/orders/queue', { query: [['status', 'received']], status: 200 }),
        request('Only preparing', 'GET', '/orders/queue', { query: [['status', 'preparing']], status: 200 }),
        request('Invalid filter -> 400 INVALID_STATUS_FILTER', 'GET', '/orders/queue', {
          query: [['status', 'ready']],
          status: 400,
          tests: [expectCode('INVALID_STATUS_FILTER')],
        }),
        request('Ready for pickup', 'GET', '/orders/ready', { status: 200 }),
        request('Finished (last 20)', 'GET', '/orders/finished', { status: 200 }),
      ],
    },
    {
      name: '2. Create',
      item: [
        request('Create order -> 201 (saves orderId)', 'POST', '/orders', {
          body: newOrder('Nora Blake', { is_vip: true }),
          status: 201,
          tests: [expectOrderStatus('received'), saveId('orderId')],
        }),
        request('Create order to cancel -> 201 (saves cancelOrderId)', 'POST', '/orders', {
          body: newOrder('Omar Haddad', { type: 'delivery', items: [{ menu_item_id: 4, quantity: 1 }] }),
          status: 201,
          tests: [saveId('cancelOrderId')],
        }),
        request('Empty items -> 400 VALIDATION_ERROR', 'POST', '/orders', {
          body: newOrder('Nora Blake', { items: [] }),
          status: 400,
          tests: [expectCode('VALIDATION_ERROR')],
        }),
        request('Unknown menu item -> 400 VALIDATION_ERROR', 'POST', '/orders', {
          body: newOrder('Nora Blake', { items: [{ menu_item_id: 9999, quantity: 1 }] }),
          status: 400,
          tests: [expectCode('VALIDATION_ERROR')],
        }),
        request('Several invalid fields -> 400, all listed', 'POST', '/orders', {
          body: {
            customer_name: '',
            type: 'catering',
            is_vip: 'yes',
            promised_at: 'tomorrow',
            items: [{ menu_item_id: 1, quantity: 0 }],
          },
          status: 400,
          tests: [
            expectCode('VALIDATION_ERROR'),
            "pm.test('lists every invalid field', () => pm.expect(pm.response.json().error.details.errors.map((e) => e.field)).to.eql(['customer_name', 'type', 'is_vip', 'promised_at', 'items[0].quantity']));",
          ],
        }),
        request('Malformed JSON -> 400 BAD_REQUEST', 'POST', '/orders', {
          rawBody: '{ "customer_name": "Nora", ',
          status: 400,
          tests: [expectCode('BAD_REQUEST')],
        }),
      ],
    },
    {
      name: '3. Lifecycle (uses orderId)',
      item: [
        request('Start -> preparing', 'POST', '/orders/{{orderId}}/start', {
          status: 200,
          tests: [expectOrderStatus('preparing')],
        }),
        request('Start again -> 409 INVALID_TRANSITION', 'POST', '/orders/{{orderId}}/start', {
          status: 409,
          tests: [expectCode('INVALID_TRANSITION')],
          description: 'Repeating a transition is an error, not a silent success. The order is unchanged.',
        }),
        request('Cancel while preparing -> 409 INVALID_TRANSITION', 'POST', '/orders/{{orderId}}/cancel', {
          status: 409,
          tests: [expectCode('INVALID_TRANSITION')],
        }),
        request('Ready -> ready', 'POST', '/orders/{{orderId}}/ready', {
          status: 200,
          tests: [expectOrderStatus('ready')],
        }),
        request('Pickup -> picked_up', 'POST', '/orders/{{orderId}}/pickup', {
          status: 200,
          tests: [expectOrderStatus('picked_up')],
        }),
        request('Start a picked-up order -> 409 INVALID_TRANSITION', 'POST', '/orders/{{orderId}}/start', {
          status: 409,
          tests: [expectCode('INVALID_TRANSITION')],
        }),
      ],
    },
    {
      name: '4. Cancel (uses cancelOrderId)',
      item: [
        request('Skip a step: ready from received -> 409', 'POST', '/orders/{{cancelOrderId}}/ready', {
          status: 409,
          tests: [expectCode('INVALID_TRANSITION')],
        }),
        request('Cancel -> cancelled', 'POST', '/orders/{{cancelOrderId}}/cancel', {
          status: 200,
          tests: [expectOrderStatus('cancelled')],
        }),
        request('Cancel again -> 409 INVALID_TRANSITION', 'POST', '/orders/{{cancelOrderId}}/cancel', {
          status: 409,
          tests: [expectCode('INVALID_TRANSITION')],
        }),
      ],
    },
    {
      name: '5. Errors',
      item: [
        request('Unknown order -> 404 ORDER_NOT_FOUND', 'POST', '/orders/999999/start', {
          status: 404,
          tests: [expectCode('ORDER_NOT_FOUND')],
        }),
        request('Invalid id -> 400 INVALID_ORDER_ID', 'POST', '/orders/abc/start', {
          status: 400,
          tests: [expectCode('INVALID_ORDER_ID')],
        }),
        request('Unknown route -> 404 ROUTE_NOT_FOUND', 'GET', '/orders/nope/start', {
          status: 404,
          tests: [expectCode('ROUTE_NOT_FOUND')],
        }),
      ],
    },
  ],
};

fs.writeFileSync(process.argv[2], JSON.stringify(collection, null, 2) + '\n');
console.log('requests:', collection.item.reduce((n, folder) => n + folder.item.length, 0));

