// Builds ai-logs/session.jsonl (raw, email redacted) and ai-logs/session.md (readable).
const fs = require('fs');
const path = require('path');

const [source, outDir] = process.argv.slice(2);
const EMAIL = /[email removed]/g;
const REDACTED = '[email removed]';

const raw = fs.readFileSync(source, 'utf8').replace(EMAIL, REDACTED);
fs.writeFileSync(path.join(outDir, 'session.jsonl'), raw);

const entries = raw
  .split('\n')
  .filter(Boolean)
  .map((line) => {
    try {
      return JSON.parse(line);
    } catch {
      return null;
    }
  })
  .filter(Boolean);

const stripTags = (text) =>
  text
    .replace(/<system-reminder>[\s\S]*?<\/system-reminder>/g, '')
    .replace(/<local-command-stdout>[\s\S]*?<\/local-command-stdout>/g, '')
    .replace(/<command-message>[\s\S]*?<\/command-message>/g, '')
    .replace(/<command-args>\s*<\/command-args>/g, '')
    .replace(/<command-name>([\s\S]*?)<\/command-name>/g, '`$1`')
    .trim();

function renderUserText(text) {
  const pasted = text.match(/<pasted_content[^>]*>([\s\S]*?)<\/pasted_content>/);
  if (pasted) {
    const rest = stripTags(text.replace(pasted[0], ''));
    return (
      (rest ? rest + '\n\n' : '') +
      '<details><summary>Pasted: the assignment text</summary>\n\n```text\n' +
      pasted[1].trim() +
      '\n```\n</details>'
    );
  }
  return stripTags(text);
}

const quote = (text) =>
  text
    .split('\n')
    .map((line) => (line ? `> ${line}` : '>'))
    .join('\n');

function toolSummary(block) {
  const input = block.input ?? {};
  const detail =
    input.description ?? input.file_path ?? input.pattern ?? input.query ?? input.url ?? input.skill ?? '';
  return `${block.name}${detail ? `: ${String(detail).split('\n')[0].slice(0, 140)}` : ''}`;
}

const out = [];
let pendingTools = [];
let lastRole = null;
const counts = { user: 0, assistant: 0, tools: 0 };

function flushTools() {
  if (pendingTools.length === 0) return;
  out.push(
    `<details><summary>${pendingTools.length} tool call${pendingTools.length > 1 ? 's' : ''}</summary>\n\n` +
      pendingTools.map((t) => `- ${t.replace(/[<>]/g, '')}`).join('\n') +
      '\n</details>\n',
  );
  pendingTools = [];
}

function heading(role, timestamp) {
  if (lastRole === role) return;
  lastRole = role;
  const when = timestamp ? ` · ${timestamp.slice(0, 16).replace('T', ' ')} UTC` : '';
  out.push(role === 'user' ? `---\n\n### 🧑 User${when}\n` : `#### 🤖 Assistant${when}\n`);
}

for (const e of entries) {
  if (e.isSidechain || e.isMeta) continue;
  const content = e.message?.content;

  if (e.type === 'user') {
    if (e.isCompactSummary) {
      flushTools();
      lastRole = null;
      out.push(
        '---\n\n_The context window filled up here. The tool replaced the earlier messages with the summary below and the session continued._\n\n' +
          '<details><summary>Context summary written by the tool</summary>\n\n' +
          quote(typeof content === 'string' ? content : content.map((p) => p.text ?? '').join('\n')) +
          '\n</details>\n',
      );
      continue;
    }
    const texts =
      typeof content === 'string'
        ? [content]
        : (content ?? []).filter((p) => p.type === 'text').map((p) => p.text);
    const declined = (Array.isArray(content) ? content : []).filter(
      (p) => p.type === 'tool_result' && JSON.stringify(p.content ?? '').includes("doesn't want to proceed"),
    );
    const text = texts.map(renderUserText).filter(Boolean).join('\n\n');
    if (!text && declined.length === 0) continue;
    flushTools();
    heading('user', e.timestamp);
    if (declined.length) out.push('_Declined the proposed tool call._\n');
    if (text) {
      counts.user++;
      out.push(quote(text) + '\n');
    }
