  if (lastRole === role) return;
  lastRole = role;
  const when = timestamp ? ` · ${timestamp.slice(0, 16).replace('T', ' ')} UTC` : '';
  out.push(role === 'user' ? `---\n\n### 🧑 User${when}\n` : `#### 🤖 Assistant${when}\n`);
}

for (const e of entries) {
  if (e.isSidechain || e.isMeta) continue;
  const content = e.message?.content;

  if (e.type === 'user') {
    if (e.isCompactSummary) {
      flushTools();
      lastRole = null;
      out.push(
        '---\n\n_The context window filled up here. The tool replaced the earlier messages with the summary below and the session continued._\n\n' +
          '<details><summary>Context summary written by the tool</summary>\n\n' +
          quote(typeof content === 'string' ? content : content.map((p) => p.text ?? '').join('\n')) +
          '\n</details>\n',
      );
      continue;
    }
    const texts =
      typeof content === 'string'
        ? [content]
        : (content ?? []).filter((p) => p.type === 'text').map((p) => p.text);
    const declined = (Array.isArray(content) ? content : []).filter(
      (p) => p.type === 'tool_result' && JSON.stringify(p.content ?? '').includes("doesn't want to proceed"),
    );
    const text = texts.map(renderUserText).filter(Boolean).join('\n\n');
    if (!text && declined.length === 0) continue;
    flushTools();
    heading('user', e.timestamp);
    if (declined.length) out.push('_Declined the proposed tool call._\n');
    if (text) {
      counts.user++;
      out.push(quote(text) + '\n');
    }
    continue;
