    }
    const text = texts.map(renderUserText).filter(Boolean).join('\n\n');
    if (!text && declined.length === 0) continue;
    flushTools();
    heading('user', e.timestamp);
    if (declined.length) out.push('_Declined the proposed tool call._\n');
    if (text) {
      counts.user++;
      out.push(quote(text) + '\n');
    }
    continue;
  }

  if (e.type === 'assistant' && Array.isArray(content)) {
    for (const block of content) {
      if (block.type === 'tool_use') {
        heading('assistant', e.timestamp);
        pendingTools.push(toolSummary(block));
        counts.tools++;
      } else if (block.type === 'text' && block.text.trim()) {
        flushTools();
        heading('assistant', e.timestamp);
        counts.assistant++;
        out.push(block.text.trim() + '\n');
      }
    }
  }
}
flushTools();

const header =
  '# Session transcript\n\n' +
  'Readable version of [`session.jsonl`](session.jsonl). It keeps every message from the user and every reply from the assistant, in order. ' +
  'Tool calls (reading files, running commands, searching the web) are listed in collapsed blocks with their one-line description; their outputs are only in the raw file. ' +
  'The internal reasoning blocks are omitted here and kept in the raw file.\n\n' +
  `${counts.user} user messages · ${counts.assistant} assistant replies · ${counts.tools} tool calls\n\n`;

fs.writeFileSync(path.join(outDir, 'session.md'), header + out.join('\n'));
console.log(counts, 'emails left:', (raw.match(EMAIL) || []).length);
